package com.osrsbestinslot.export;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Who is standing next to you while a shop is open, nearest first.
 *
 * The plugin already computes this list every tick to attach to a store event. This renders the
 * same list and captures nothing new — no extra data is read and none leaves the client.
 *
 * The reset countdown used to live here and was SPLIT OUT on 2026-09-03: this list changes length
 * as players walk past, and a growing panel dragged the countdown around with it. See
 * StoreResetOverlay.
 *
 * Shows ONLY while a shop interface is open. Movable, so placement is the user's choice.
 */
class StoreNearbyOverlay extends OverlayPanel
{
	/** Rows to draw. The event payload caps at 24; a panel that tall would cover the shop. */
	static final int DISPLAY_CAP = 6;

	/**
	 * An OSRS display name is at most 12 characters, so EVERY real RSN must fit — truncating one
	 * would name the wrong player. The panel is sized for 12 plus the right column instead.
	 * The guard stays for anything longer than a real name could be.
	 */
	static final int RSN_MAX_CHARS = 12;

	/** Fixed width: 12-char RSN plus the right column. Also what the anchor subtracts to right-align. */
	static final int PANEL_WIDTH = 196;

	/** Beyond this many tiles a player cannot be the counterparty of a store hand-off. */
	static final int DISPLAY_RANGE_TILES = 15;

	/**
	 * A deliberately QUIET palette. The countdown is the thing the user acts on and it owns the loud
	 * colours (StoreResetOverlay); if this list shouted too, neither would read at a glance. Only
	 * the adjacent player — the plausible counterparty — gets an accent.
	 */
	private static final Color GOLD = new Color(255, 193, 71);
	private static final Color NAME = new Color(225, 225, 225);
	private static final Color NEAR = new Color(190, 190, 190);
	private static final Color DIM = new Color(140, 140, 140);

	/** Matches StoreResetOverlay: one plate colour across both overlays. */
	private static final Color PLATE = new Color(26, 26, 26, 235);

	private final AccountConnectPlugin plugin;

	StoreNearbyOverlay(AccountConnectPlugin plugin)
	{
		super(plugin);
		this.plugin = plugin;
		// Option D: sits under the reset timer on the right. Both stay draggable.
		// DYNAMIC: the plugin supplies a live location each frame (under the shop's item grid) —
		// see anchorUnderItems below. A fixed corner cannot follow a window that moves with the
		// client size, and "below the items" is what was asked for.
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		// Let the user drag it where they want in overlay edit mode. Placement is taste, not policy.
		setMovable(true);
		setSnappable(true);
		panelComponent.setPreferredSize(new Dimension(PANEL_WIDTH, 0));	// 12-char RSN + "12 tiles  126"
		// Same plate as the countdown so the two read as one design, not two accidents.
		panelComponent.setBackgroundColor(PLATE);
		panelComponent.setBorder(new java.awt.Rectangle(6, 4, 6, 4));
		panelComponent.setGap(new java.awt.Point(0, 2));	// default 0 makes rows collide
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		anchorUnderItems();
		// Two gates, both required: a shop is open, and the backend granted store tools to this
		// token. The second is what keeps these overlays off every ordinary player's screen.
		if (!plugin.isShopOpen() || !plugin.storeToolsEnabled())
		{
			return null;
		}

		// No "Store" title any more: the countdown left for its own overlay, and "Nearby (N)"
		// already names this panel. One less line covering the shop.
		List<String[]> rows = visibleRows(plugin.nearbyPlayersSnapshot(DISPLAY_CAP));

		panelComponent.getChildren().add(TitleComponent.builder()
			.text(rows.isEmpty() ? "Nobody nearby" : "Nearby (" + rows.size() + ")")
			.color(rows.isEmpty() ? DIM : NAME)
			.build());

		for (String[] row : rows)
		{
			int dist = Integer.parseInt(row[2]);
			panelComponent.getChildren().add(LineComponent.builder()
				.left(row[0])
				.right(row[1])
				.leftColor(dist <= 1 ? GOLD : NAME)
				.rightColor(distanceColor(dist))
				.build());
		}

		builtRows = panelComponent.getChildren().size();
		return super.render(graphics);
	}

	/**
	 * Park this list under the reset timer, which itself sits under the shop's item grid, unless
	 * the user has dragged it. setPreferredLocation is what RuneLite persists on a drag, so writing
	 * it every frame would pin the overlay and silently undo their placement — hence once per visit.
	 */
	private void anchorUnderItems()
	{
		if (anchored)
		{
			return;
		}
		java.awt.Point p = plugin.shopItemsBottomLeft();
		if (p == null)
		{
			return;		// widget not laid out yet — try again next frame
		}
		if (getPreferredLocation() == null)
		{
			// Right-aligned to the same grid edge as the countdown (p.x is that edge), and pushed
			// down by the countdown's own height so the two stack without touching.
			setPreferredLocation(new java.awt.Point(p.x - PANEL_WIDTH, p.y + 32));
		}
		anchored = true;
	}

	/** One anchor per visit; cleared when the shop closes so the next visit re-places it. */
	private boolean anchored;

	void resetAnchorForVisit()
	{
		anchored = false;
	}

	/** Gold for the tile next to you — the plausible counterparty — fading out with distance. */
	static Color distanceColor(int dist)
	{
		if (dist <= 1)
		{
			return GOLD;
		}
		return dist <= 5 ? NEAR : DIM;
	}

	/** How many lines the last render BUILT, before OverlayPanel cleared them. Test seam only. */
	private int builtRows;

	int builtRowCountForTest()
	{
		return builtRows;
	}

	/**
	 * Trim an RSN that would wrap. A wrapped name pushes its own right column onto the next line and
	 * every row below it reads against the wrong player — worse than a truncated name.
	 */
	static String shortenRsn(String rsn)
	{
		if (rsn == null)
		{
			return "";
		}
		if (rsn.length() <= RSN_MAX_CHARS)
		{
			return rsn;
		}
		return rsn.substring(0, RSN_MAX_CHARS - 1) + "\u2026";
	}

	/**
	 * Turn the plugin's nearby[] maps into display rows: {left, right, distance}.
	 *
	 * Pure and static so the filtering and formatting are testable without a game client or a
	 * Graphics2D. Skips any entry missing the two fields it needs rather than drawing a broken row.
	 */
	static List<String[]> visibleRows(List<Map<String, Object>> nearby)
	{
		List<String[]> out = new ArrayList<>();
		if (nearby == null)
		{
			return out;
		}
		for (Map<String, Object> p : nearby)
		{
			Object rsnValue = p.get("rsn");
			Object distValue = p.get("dist");
			if (!(rsnValue instanceof String) || !(distValue instanceof Integer))
			{
				continue;
			}
			int dist = (Integer) distValue;
			if (dist > DISPLAY_RANGE_TILES)
			{
				continue;
			}
			String right = dist <= 1 ? "beside you" : dist + " tiles";
			Object cb = p.get("cb");
			if (cb instanceof Integer)
			{
				right = right + "  lvl " + cb;
			}
			out.add(new String[]{shortenRsn((String) rsnValue), right, String.valueOf(dist)});
			if (out.size() >= DISPLAY_CAP)
			{
				break;
			}
		}
		return out;
	}
}

package com.osrsbestinslot.export;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

/**
 * The store reset countdown, ON ITS OWN so it never moves.
 *
 * Split out of the combined panel on 2026-09-03 for one measured reason: the nearby list changes
 * length every few ticks as players walk past, and a panel anchored by its bottom edge grows and
 * shrinks upward — so the countdown jittered between positions and was hard to read at a glance.
 * A separate overlay drawing exactly ONE row can never change height, so it sits still.
 *
 * The number is the thing the user acts on, so it gets its own fixed spot and the strongest colour.
 */
class StoreResetOverlay extends OverlayPanel
{
	/** Under this many seconds, do not start a hand-off — the window is closing. */
	static final int URGENT_SECONDS = 12;

	/** Above this many seconds there is comfortable room to work. */
	static final int SAFE_SECONDS = 25;

	static final Color GREEN = new Color(106, 214, 106);
	static final Color AMBER = new Color(245, 184, 56);
	static final Color RED = new Color(232, 88, 88);
	static final Color DIM = new Color(140, 140, 140);
	private static final Color LABEL = new Color(215, 215, 215);

	/** The mockup's plate: near-opaque so text never fights the game scene behind it. */
	private static final Color PLATE = new Color(26, 26, 26, 235);

	/**
	 * ONE fixed width, always. A width that tracks its content is the other half of the jitter:
	 * "8s" and "sell junk" are very different lengths, so the panel edge would jump on every
	 * rollover. Sized for the longest string this overlay can ever draw.
	 */
	private static final int PANEL_WIDTH = 112;

	private final AccountConnectPlugin plugin;

	StoreResetOverlay(AccountConnectPlugin plugin)
	{
		super(plugin);
		this.plugin = plugin;
		// Option D (operator choice, 2026-09-03): both overlays on the RIGHT, clear of the item grid.
		// DYNAMIC: the plugin supplies a live location each frame (under the shop's item grid) —
		// see anchorUnderItems below. A fixed corner cannot follow a window that moves with the
		// client size, and "below the items" is what was asked for.
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setMovable(true);
		setSnappable(true);
		panelComponent.setPreferredSize(new Dimension(PANEL_WIDTH, 0));
		// STYLE, to match the signed-off mockup: a solid dark plate rather than RuneLite's default
		// translucent grey, which let the game scene bleed through and made the text hard to read
		// against a bright shop. Tighter border and row gap than the default so the plate reads as
		// one deliberate object instead of a loose stack.
		panelComponent.setBackgroundColor(PLATE);
		panelComponent.setBorder(new java.awt.Rectangle(6, 4, 6, 4));
		panelComponent.setGap(new java.awt.Point(0, 2));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		anchorUnderItems();
		if (!plugin.isShopOpen() || !plugin.storeToolsEnabled())
		{
			return null;
		}

		long remainMs = plugin.msUntilNextResetForDisplay();
		lastText = resetText(remainMs);
		lastColor = remainMs <= 0 ? DIM : countdownColor((int) ((remainMs + 999) / 1000));

		// EXACTLY ONE ROW, on every path. This is what keeps the overlay still.
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Reset")
			.leftColor(LABEL)
			.right(lastText)
			.rightColor(lastColor)
			.build());

		builtRows = panelComponent.getChildren().size();
		return super.render(graphics);
	}

	/**
	 * Park this overlay under the shop's item grid, unless the user has dragged it somewhere.
	 *
	 * setPreferredLocation is what RuneLite persists when a user moves an overlay in edit mode, so
	 * writing it every frame would pin the overlay and silently undo their drag. The default is
	 * therefore applied ONCE per shop visit; after that the position is theirs.
	 */
	private void anchorUnderItems()
	{
		if (anchored)
		{
			return;
		}
		java.awt.Point p = plugin.shopItemsBottomLeft();
		if (p == null)
		{
			return;		// widget not laid out yet — try again next frame
		}
		if (getPreferredLocation() == null)
		{
			// p.x is the grid's RIGHT edge, so subtract our own width to end flush with it. Both
			// overlays do this, so their right edges line up whatever each one's width is.
			setPreferredLocation(new java.awt.Point(p.x - PANEL_WIDTH, p.y));
		}
		anchored = true;
	}

	/** One anchor per visit; cleared when the shop closes so the next visit re-places it. */
	private boolean anchored;

	void resetAnchorForVisit()
	{
		anchored = false;
	}

	/** Green with room to work, amber as it tightens, red when a hand-off should not be started. */
	static Color countdownColor(int secs)
	{
		if (secs <= URGENT_SECONDS)
		{
			return RED;
		}
		return secs >= SAFE_SECONDS ? GREEN : AMBER;
	}

	/**
	 * The countdown, or what it is waiting for.
	 *
	 * Never blank: a silent overlay is indistinguishable from a broken one, and that is exactly how
	 * the first live test read ("store reset not appearing anywhere"). Whole seconds, rounded UP so
	 * it never shows 0s — the last second reads 1s and then rolls to 60s.
	 */
	static String resetText(long remainMs)
	{
		if (remainMs <= 0)
		{
			return "sell junk";
		}
		return ((int) ((remainMs + 999) / 1000)) + "s";
	}

	/* Test seams: OverlayPanel clears its children after render, so the drawn values are
	 * otherwise unobservable. */
	private String lastText = "";
	private Color lastColor;
	private int builtRows;

	/** Rows the last render BUILT — OverlayPanel clears them afterwards, so this is the only view. */
	int builtRowCountForTest()
	{
		return builtRows;
	}

	String lastTextForTest()
	{
		return lastText;
	}

	Color lastColorForTest()
	{
		return lastColor;
	}
}

/*
 * Buffers the last N rendered frames for the store delivery-proof burst (frames uploaded raw; the server stitches — no encoder in the plugin).
 *
 * A bounded ring buffer of ALREADY-ENCODED JPEG frames. The recorder pushes the last few
 * seconds of frames in; when the shop closes, the buffer is snapshotted and uploaded off the
 * client thread. Oldest frames are evicted once the capacity is reached, so memory stays
 * bounded regardless of how long a shop stays open.
 *
 * ⚠ The ring holds byte[], NOT BufferedImage, and that is load-bearing (fixed 2026-09-02).
 * It used to hold raw BufferedImages, which at 30fps x 12s x 704px is ~1.1MB per frame and
 * ~400MB retained for the length of a shop visit — past RuneLite's 512MB default max heap, so
 * the client froze in continuous GC and the burst never uploaded. Encoded, the same 360 frames
 * are ~30KB each, about 11MB. Never store decoded images here.
 *
 * Standalone + unit-testable: it depends only on the JDK (no RuneLite, no AWT), so the
 * frame -> buffer path can be driven with synthetic byte arrays under test.
 */
package com.osrsbestinslot.export;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

/** Fixed-capacity FIFO of the most recent ENCODED frames. Thread-safe (encode thread adds, upload thread snapshots). */
public class ClipRingBuffer
{
	private final int capacity;
	private final Deque<byte[]> frames;

	/**
	 * @param capacity max frames retained (= fps * seconds). Must be &gt;= 1.
	 */
	public ClipRingBuffer(int capacity)
	{
		if (capacity < 1)
		{
			throw new IllegalArgumentException("capacity must be >= 1");
		}
		this.capacity = capacity;
		this.frames = new ArrayDeque<>(capacity);
	}

	/** Append an encoded frame, evicting the oldest if at capacity. Null / empty frames are ignored. */
	public synchronized void add(byte[] frame)
	{
		if (frame == null || frame.length == 0)
		{
			return;
		}
		if (frames.size() >= capacity)
		{
			frames.pollFirst();
		}
		frames.addLast(frame);
	}

	/** Ordered copy (oldest -&gt; newest) for the uploader. */
	public synchronized List<byte[]> snapshot()
	{
		return new ArrayList<>(frames);
	}

	/** Total retained bytes — the number this class exists to bound. */
	public synchronized long byteSize()
	{
		long total = 0;
		for (byte[] f : frames)
		{
			total += f.length;
		}
		return total;
	}

	public synchronized int size()
	{
		return frames.size();
	}

	public int capacity()
	{
		return capacity;
	}

	public synchronized void clear()
	{
		frames.clear();
	}
}

/*
 * OSRS Best in Slot — account-connect export plugin.
 *
 * Reads the logged-in account's game state and POSTs a versioned JSON snapshot to the
 * osrsbestinslot.com ingest endpoint, keyed by a link token the player pastes from the site.
 * The calculators read the snapshot back (by the same token) to auto-fill inputs/settings.
 *
 * Plumbing idioms (injected Client/Gson/OkHttpClient/ItemManager, @Schedule on the client thread,
 * async OkHttp enqueue) follow the open-source WikiSync plugin by andmcadams (BSD-2-Clause) as the
 * reference implementation — credited. The data model is original to the osrsbestinslot contract.
 *
 * schema_v stays 1: the live endpoint accepts schema_v<=1 and stores extra fields opaquely, so
 * adding fields here is plugin-only (no server change). Do NOT bump schema_v without also raising
 * the endpoint cap in the same change.
 *
 * Captured this pass (all via named RuneLite constants / clean APIs — no guessed ids):
 *   skills (xp/level/boosted), quests (Quest.getState), worn equipment + inventory, account meta,
 *   achievement diaries (48 Varbits.DIARY_*), combat-achievement tiers (6), slayer (points/streak/
 *   current task), bank + bank value (ItemManager prices, gated on the bank being opened), wealth.
 * Deferred (flagged false): collection log (cache walk), boss KC (no clean client field).
 * Diary/CA values are captured RAW (lossless ints) — the raw->done decode is done server-side once
 * the values are confirmed against a real account.
 */
package com.osrsbestinslot.export;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
