/**
 * WAVE 4 — structured loot events. All four loot classes were javap-verified present in client 1.12.32;
 * we consume ServerNpcLoot (NPC) + PlayerLootReceived (PvP), mirroring RuneLite's own LootTrackerPlugin
 * to avoid the ServerNpcLoot/NpcLootReceived double-fire. These tests exercise the emit + adapter logic
 * with real ItemStacks and mocked NPCComposition/Player; the events are fired by LootManager (a core
 * service) at runtime, which no unit test can stand in for.
 */
public class Wave4LootTest
{
	private static final String TEST_TOKEN = "0123456789abcdef0123456789abcdef";

	private static AccountConnectConfig onConfig()
	{
		return new AccountConnectConfig()
		{
			@Override public boolean enableUpload() { return true; }

			@Override
			public String linkToken()
			{
				return TEST_TOKEN;
			}
		};
	}

	@Test
	public void emitLootBuffersItemsAndSource() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		plugin.emitLoot("Goblin", "npc", Arrays.asList(new ItemStack(995, 40), new ItemStack(526, 1)));

		assertEquals(1, plugin.pendingEvents.size());
		Map<String, Object> ev = plugin.pendingEvents.get(0);
		assertEquals("loot", ev.get("type"));
		assertEquals("Goblin", ev.get("source_name"));
		assertEquals("npc", ev.get("source_type"));
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> items = (List<Map<String, Object>>) ev.get("items");
		assertEquals("one kill's drops coalesce into one event", 2, items.size());
		assertEquals(995, items.get(0).get("id"));
		assertEquals(40, items.get(0).get("qty"));
		assertEquals(0L, ev.get("value")); // no ItemManager injected → value 0, still present
	}

	@Test
	public void emitLootValuesViaItemManager() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		ItemManager im = mock(ItemManager.class);
		when(im.getItemPrice(995)).thenReturn(1);
		when(im.getItemPrice(560)).thenReturn(200);
		inject(plugin, "itemManager", im);

		plugin.emitLoot("Vorkath", "npc", Arrays.asList(new ItemStack(995, 5000), new ItemStack(560, 100)));

		Map<String, Object> ev = plugin.pendingEvents.get(0);
		assertEquals(5000L + 200L * 100L, ev.get("value")); // 5000 + 20000 = 25000
	}

	@Test
	public void emitLootSkipsBlankStacksAndEmptyDrops() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());

		plugin.emitLoot("Goblin", "npc", Collections.emptyList());
		assertTrue("empty drop → no event", plugin.pendingEvents.isEmpty());

		plugin.emitLoot("Goblin", "npc", Arrays.asList(new ItemStack(-1, 5), new ItemStack(995, 0)));
		assertTrue("all-blank drop → no event", plugin.pendingEvents.isEmpty());

		plugin.emitLoot("Goblin", "npc", Arrays.asList(new ItemStack(-1, 5), new ItemStack(526, 3)));
		assertEquals(1, plugin.pendingEvents.size());
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> items = (List<Map<String, Object>>) plugin.pendingEvents.get(0).get("items");
		assertEquals("only the real item survives", 1, items.size());
		assertEquals(526, items.get(0).get("id"));
	}

	@Test
	public void onServerNpcLootEmitsNpcLoot() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		NPCComposition comp = mock(NPCComposition.class);
		when(comp.getName()).thenReturn("Zulrah");
		ServerNpcLoot event = new ServerNpcLoot(comp, Collections.singletonList(new ItemStack(12934, 250)));

		plugin.onServerNpcLoot(event);

		Map<String, Object> ev = plugin.pendingEvents.get(0);
		assertEquals("loot", ev.get("type"));
		assertEquals("npc", ev.get("source_type"));
		assertEquals("Zulrah", ev.get("source_name"));
	}

	@Test
	public void onPlayerLootWithholdsVictimName() throws Exception
	{
		// Compliance: capture the PvP loot ITEMS but never the killed player's name (product decision, TODO).
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Player victim = mock(Player.class);
		PlayerLootReceived event = new PlayerLootReceived(victim, Collections.singletonList(new ItemStack(11832, 1)));

		plugin.onPlayerLootReceived(event);

		Map<String, Object> ev = plugin.pendingEvents.get(0);
		assertEquals("loot", ev.get("type"));
		assertEquals("player", ev.get("source_type"));
		assertFalse("victim name must NOT be sent", ev.containsKey("source_name"));
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> items = (List<Map<String, Object>>) ev.get("items");
		assertEquals(11832, items.get(0).get("id"));
	}

	@Test
	public void lootGatedOnToken() throws Exception
	{
		// No token → activity log inactive → loot buffers nothing (same gate as every event).
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", new AccountConnectConfig() {
			@Override public boolean enableUpload() { return true; }
});
		plugin.emitLoot("Goblin", "npc", Collections.singletonList(new ItemStack(995, 10)));
		assertTrue(plugin.pendingEvents.isEmpty());
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

package com.osrsbestinslot.export;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import org.junit.Test;

import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

/**
 * The visibility gate, exercised through the REAL RuneLite OverlayPanel render path against a real
 * Graphics2D. A unit test of the row builder cannot catch an overlay that draws in the wrong state,
 * and drawing over the game outside a shop is this feature's worst failure.
 */
public class StoreNearbyOverlayRenderTest
{
	/**
	 * A plugin with a linked token. storeToolsEnabled() requires BOTH the server grant and a linked
	 * token, so a config-less plugin cannot represent either state honestly.
	 */
	private static AccountConnectPlugin plugin() throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		java.lang.reflect.Field f = AccountConnectPlugin.class.getDeclaredField("config");
		f.setAccessible(true);
		f.set(p, new AccountConnectConfig()
		{
			@Override
			public boolean enableUpload()
			{
				return true;
			}

			@Override
			public String linkToken()
			{
				return "0123456789abcdef0123456789abcdef";
			}
		});
		return p;
	}

	private static Graphics2D graphics()
	{
		BufferedImage img = new BufferedImage(400, 300, BufferedImage.TYPE_INT_ARGB);
		return img.createGraphics();
	}

	@Test
	public void drawsNothingWhileNoShopIsOpen() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		plugin.setShopOpenForTest(false);
		StoreNearbyOverlay overlay = new StoreNearbyOverlay(plugin);
		assertNull("overlay must not render outside a shop", overlay.render(graphics()));
	}

	@Test
	public void drawsWhileAShopIsOpen() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		plugin.setShopOpenForTest(true);
		plugin.setStoreToolsForTest(true);
		StoreNearbyOverlay overlay = new StoreNearbyOverlay(plugin);
		// No client is injected, so nearbyPlayersSnapshot returns empty — the panel must still draw
		// its title and the explicit "nobody nearby" line rather than vanishing.
		Dimension d = overlay.render(graphics());
		assertNotNull("overlay must render while a shop is open", d);
		// OverlayPanel clears its children at the END of render, so inspect what it BUILT. A panel
		// with only a title is indistinguishable from one whose data source silently broke — the
		// explicit empty-state line is what tells those apart, so assert it is actually produced.
		java.util.List<String[]> rows = StoreNearbyOverlay.visibleRows(plugin.nearbyPlayersSnapshot(6));
		org.junit.Assert.assertTrue("no client injected, so the row list must be empty", rows.isEmpty());
		// One line: the "Nobody nearby" heading. The reset countdown is its own overlay now.
		org.junit.Assert.assertEquals("empty-state heading only",
			1, overlay.builtRowCountForTest());
	}



	/**
	 * THE GATE. These overlays render other players' names, and they are granted only by the
	 * backend to an allowlisted token. A regular player must see nothing even inside a shop.
	 */
	@Test
	public void drawsNothingWhenTheServerHasNotGrantedStoreTools() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		plugin.setShopOpenForTest(true);
		// store tools deliberately NOT granted — this is every ordinary player's state
		StoreNearbyOverlay overlay = new StoreNearbyOverlay(plugin);
		assertNull("ungranted tokens must see no overlay", overlay.render(graphics()));
	}

	/**
	 * THE DEV OVERRIDE IS OFF UNLESS A JVM FLAG SETS IT, and only the exact grant words count.
	 * A Hub build launched normally has no such property, so this can never leak to a player.
	 */
	@Test
	public void theDevOverrideIsOffWithoutTheFlagAndRefusesJunkValues() throws Exception
	{
		System.clearProperty("osrsbis.storetools");
		org.junit.Assert.assertFalse("no flag = no override",
			AccountConnectPlugin.storeToolsDevOverride());
		try
		{
			for (String bad : new String[]{"", " ", "off", "false", "0", "yes", "ON"})
			{
				System.setProperty("osrsbis.storetools", bad);
				org.junit.Assert.assertFalse("'" + bad + "' must not grant",
					AccountConnectPlugin.storeToolsDevOverride());
			}
			for (String good : new String[]{"on", "true", "1"})
			{
				System.setProperty("osrsbis.storetools", good);
				org.junit.Assert.assertTrue("'" + good + "' must grant",
					AccountConnectPlugin.storeToolsDevOverride());
			}
		}
		finally
		{
			System.clearProperty("osrsbis.storetools");
		}
	}

	/** The override still requires a linked token — it bypasses the server, not the account. */
	@Test
	public void theDevOverrideStillRequiresALinkedToken() throws Exception
	{
		System.setProperty("osrsbis.storetools", "on");
		try
		{
			AccountConnectPlugin unlinked = new AccountConnectPlugin();
			java.lang.reflect.Field f = AccountConnectPlugin.class.getDeclaredField("config");
			f.setAccessible(true);
			f.set(unlinked, new AccountConnectConfig()
			{
				@Override
				public boolean enableUpload()
				{
					return true;
				}

				@Override
				public String linkToken()
				{
					return "";
				}
			});
			org.junit.Assert.assertFalse("no token = no overlays even with the flag",
				unlinked.storeToolsEnabled());
			org.junit.Assert.assertTrue("linked token + flag = granted", plugin().storeToolsEnabled());
		}
		finally
		{
			System.clearProperty("osrsbis.storetools");
		}
	}

	@Test
	public void theGateDefaultsToOff() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		org.junit.Assert.assertFalse("store tools must default OFF", plugin.storeToolsEnabled());
	}

	@Test
	public void repeatedRendersDoNotAccumulateRows() throws Exception
	{
		// OverlayPanel clears its children between frames only when clearChildren is on. If it is
		// not, the panel grows one row per frame and covers the screen within seconds.
		AccountConnectPlugin plugin = plugin();
		plugin.setShopOpenForTest(true);
		plugin.setStoreToolsForTest(true);
		StoreNearbyOverlay overlay = new StoreNearbyOverlay(plugin);
		overlay.render(graphics());
		int afterFirst = overlay.getPanelComponent().getChildren().size();
		for (int i = 0; i < 20; i++)
		{
			overlay.render(graphics());
		}
		int afterMany = overlay.getPanelComponent().getChildren().size();
		org.junit.Assert.assertEquals("panel children grew across frames", afterFirst, afterMany);
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigManager;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;

/**
 * The orphaned {@code uploadTradeScreenshots} key.
 *
 * Its config item was deleted when delivery-proof screenshots became part of core sync, but RuneLite
 * keeps a stored value whose item is gone, so the key is still in every upgraded profile. It was read
 * out of a live profile on 2026-09-15. Nothing reads it, so the risk is not behaviour: it is that a
 * profile file advertises a toggle the code does not have.
 */
public class OrphanConfigKeyTest
{
	@Test
	public void startUpUnsetsTheOrphanedKey() throws Exception
	{
		AccountConnectPlugin plugin = UploadSwitchTest.plugin(false, "");
		ConfigManager cm = mock(ConfigManager.class);
		inject(plugin, "configManager", cm);

		Method startUp = AccountConnectPlugin.class.getDeclaredMethod("startUp");
		startUp.setAccessible(true);
		startUp.invoke(plugin);

		verify(cm, times(1)).unsetConfiguration(
			AccountConnectPlugin.CONFIG_GROUP, AccountConnectPlugin.ORPHAN_SCREENSHOT_KEY);
	}

	/** A missing ConfigManager must not throw — startUp runs before injection in some test paths. */
	@Test
	public void aMissingConfigManagerIsASafeNoOp() throws Exception
	{
		AccountConnectPlugin plugin = UploadSwitchTest.plugin(false, "");
		inject(plugin, "configManager", null);
		plugin.removeOrphanedKeys();
	}

	/** And the key must genuinely be orphaned — if an item ever declares it again, this unset is a bug. */
	@Test
	public void theKeyIsNotDeclaredByAnyConfigItem()
	{
		for (Method m : AccountConnectConfig.class.getDeclaredMethods())
		{
			ConfigItem item = m.getAnnotation(ConfigItem.class);
			if (item == null)
			{
				continue;
			}
			assertFalse("no live config item may own the orphaned key",
				AccountConnectPlugin.ORPHAN_SCREENSHOT_KEY.equals(item.keyName()));
		}
	}

	private static void inject(AccountConnectPlugin p, String name, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		f.set(p, value);
	}
}

package com.osrsbestinslot.export;

import com.sun.net.httpserver.HttpServer;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.lang.reflect.Field;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.ui.DrawManager;
import okhttp3.OkHttpClient;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for the trade-screenshot path — no live client needed. Covered here: PNG encoding
 * (valid magic bytes from a synthetic frame), the toggle-off early-return (no capture, no state),
 * and the state machine's arm / commit / discard transitions including a real multipart POST to a
 * local JDK HttpServer stub. NOT coverable without a live client (manual test plan in the report):
 * real WidgetLoaded/ChatMessage event delivery order on a live trade, actual game-frame contents,
 * Guice injection wiring, and the production ingest endpoint.
 */
public class TradeScreenshotTest
{
	private static final byte[] PNG_MAGIC = {(byte) 0x89, 'P', 'N', 'G', 0x0D, 0x0A, 0x1A, 0x0A};
	private static final String TEST_TOKEN = "0123456789abcdef0123456789abcdef";

	// ---- PNG encode path ----

	@Test
	public void encodePngProducesValidNonEmptyPng()
	{
		byte[] bytes = AccountConnectPlugin.encodePng(syntheticFrame(320, 240));
		assertNotNull("encode returned null", bytes);
		assertTrue("PNG is empty", bytes.length > 0);
		for (int i = 0; i < PNG_MAGIC.length; i++)
		{
			assertEquals("PNG magic byte " + i + " wrong", PNG_MAGIC[i], bytes[i]);
		}
	}

	@Test
	public void toBufferedImagePassesThroughAndEncodesEndToEnd()
	{
		BufferedImage converted = AccountConnectPlugin.toBufferedImage(syntheticFrame(64, 48));
		byte[] bytes = AccountConnectPlugin.encodePng(converted);
		assertNotNull(bytes);
		assertTrue(startsWith(bytes, PNG_MAGIC));
	}

	// ---- NOT LINKED: handlers return early, nothing captured ----

	@Test
	public void unlinkedPerformsNoCaptureAndHoldsNoState() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		// Defaults only: linkToken() == "" so screenshotsEnabled() is false (the separate opt-in toggle
		// was removed 2026-09-02 — the token is the gate). drawManager / executor / okHttpClient are
		// left null on purpose — if any handler got past the gate and tried to capture or upload, it
		// would NPE and fail this test.
		inject(plugin, "config", new AccountConnectConfig() {
			@Override public boolean enableUpload() { return true; }
});

		plugin.handleTradeContainerChanged(90);
		assertFalse("toggle off must not arm tradeActive", plugin.tradeActive);

		plugin.handleTradeWidgetLoaded(334);
		assertNull("toggle off must not buffer a frame", plugin.pendingTradeFrame.get());

		plugin.handleTradeChat("Accepted trade.");
		assertFalse(plugin.tradeActive);
		assertNull(plugin.pendingTradeFrame.get());
	}

	@Test
	public void togglingOffMidTradeDropsTheBufferedFrame() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", new AccountConnectConfig() {
			@Override public boolean enableUpload() { return true; }
});
		// Simulate a frame buffered while the toggle was on, then the toggle switched off:
		plugin.tradeActive = true;
		plugin.pendingTradeFrame.set(syntheticFrame(8, 8));

		plugin.handleTradeChat("Accepted trade.");	// guard runs first — must clear, never upload
		assertFalse(plugin.tradeActive);
		assertNull("disabled guard must drop the stale frame", plugin.pendingTradeFrame.get());
	}

	// ---- toggle ON: arm -> frame -> commit uploads one multipart PNG ----

	@Test
	public void armCommitUploadsBothConfirmAndCompletedScreenshots() throws Exception
	{
		// Delivery proof = TWO shots per completed trade: the confirm window (items + partner) and the
		// post-accept frame (the "Accepted trade." chat line, window closed). Both must reach the ingest
		// route, each tagged with its phase.
		java.util.concurrent.BlockingQueue<Capture> received = new java.util.concurrent.LinkedBlockingQueue<>();
		HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		server.createContext("/", exchange ->
		{
			byte[] reqBody = readAll(exchange.getRequestBody());
			byte[] resp = "{\"ok\":true,\"id\":1}".getBytes(StandardCharsets.UTF_8);
			exchange.sendResponseHeaders(200, resp.length);
			exchange.getResponseBody().write(resp);
			exchange.close();
			received.add(new Capture(exchange.getRequestURI().getPath(),
				exchange.getRequestHeaders().getFirst("Content-Type"), reqBody));
		});
		server.start();
		try
		{
			String base = "http://127.0.0.1:" + server.getAddress().getPort() + "/wp-json/osrsbis/v1";
			AccountConnectPlugin plugin = new AccountConnectPlugin();
			inject(plugin, "config", enabledConfig(base));
			DrawManager drawManager = new DrawManager();
			inject(plugin, "drawManager", drawManager);
			inject(plugin, "executor", Executors.newSingleThreadScheduledExecutor());
			inject(plugin, "okHttpClient", new OkHttpClient());

			plugin.handleTradeContainerChanged(90);	// trade genuinely in progress
			assertTrue(plugin.tradeActive);

			plugin.handleTradeWidgetLoaded(334);	// confirm screen -> one-shot frame request
			drawManager.processDrawComplete(() -> syntheticFrame(320, 240));	// deliver the confirm frame
			assertNotNull("frame must be buffered after 334-load + draw", plugin.pendingTradeFrame.get());

			plugin.handleTradeChat("Accepted trade.");	// commit: uploads confirm + arms the completed grab
			assertFalse(plugin.tradeActive);
			assertNull("commit must consume the buffered frame", plugin.pendingTradeFrame.get());
			drawManager.processDrawComplete(() -> syntheticFrame(320, 240));	// deliver the completed frame

			Capture a = received.poll(15, TimeUnit.SECONDS);
			Capture b = received.poll(15, TimeUnit.SECONDS);
			assertNotNull("first screenshot upload missing", a);
			assertNotNull("second (completed) screenshot upload missing", b);
			String phases = "";
			for (Capture c : new Capture[] {a, b})
			{
				assertEquals("/wp-json/osrsbis/v1/screenshot-ingest", c.path);
				assertTrue("not multipart: " + c.contentType, c.contentType.startsWith("multipart/form-data"));
				String body = new String(c.body, StandardCharsets.ISO_8859_1);
				assertTrue("token field missing", body.contains("name=\"token\"") && body.contains(TEST_TOKEN));
				assertTrue("kind field missing", body.contains("name=\"kind\"") && body.contains("trade"));
				assertTrue("phase field missing", body.contains("name=\"phase\""));
				assertTrue("captured_at field missing", body.contains("name=\"captured_at\""));
				assertTrue("file part missing", body.contains("name=\"file\""));
				assertTrue("file part not image/png", body.contains("image/png"));
				assertTrue("body carries no PNG payload", indexOf(c.body, PNG_MAGIC) >= 0);
				phases += body;
			}
			assertTrue("confirm-phase screenshot not uploaded", phases.contains("confirm"));
			assertTrue("completed-phase screenshot not uploaded", phases.contains("completed"));
		}
		finally
		{
			server.stop(0);
		}
	}

	// ---- discard paths: decline / window closed / disconnect — never upload ----

	@Test
	public void declineDiscardsFrameWithoutUpload() throws Exception
	{
		AccountConnectPlugin plugin = armedPluginWithoutNetwork();
		plugin.handleTradeChat("Other player declined trade.");
		assertFalse(plugin.tradeActive);
		assertNull(plugin.pendingTradeFrame.get());
	}

	@Test
	public void widgetClosedDiscardsFrameWithoutUpload() throws Exception
	{
		AccountConnectPlugin plugin = armedPluginWithoutNetwork();
		plugin.handleTradeWidgetClosed(334);
		assertFalse(plugin.tradeActive);
		assertFalse(plugin.tradeArmed);
		assertNull(plugin.pendingTradeFrame.get());

		plugin = armedPluginWithoutNetwork();
		plugin.handleTradeWidgetClosed(335);	// first trade screen closing while ARMED also discards
		assertFalse(plugin.tradeActive);
		assertFalse(plugin.tradeArmed);
		assertNull(plugin.pendingTradeFrame.get());
	}

	@Test
	public void firstScreenCloseBeforeConfirmDoesNotKillTheTrade() throws Exception
	{
		// Normal 335 -> 334 transition: the first trade screen closes while we are tradeActive but
		// not yet ARMED. That close must NOT reset state, or the confirm screen could never arm.
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", enabledConfig(null));
		plugin.tradeActive = true;

		plugin.handleTradeWidgetClosed(335);
		assertTrue("335 closing pre-ARMED must not clear tradeActive", plugin.tradeActive);
	}

	@Test
	public void disconnectClearsPendingFrameWithoutUpload() throws Exception
	{
		AccountConnectPlugin plugin = armedPluginWithoutNetwork();
		GameStateChanged event = new GameStateChanged();
		event.setGameState(GameState.CONNECTION_LOST);
		plugin.onGameStateChanged(event);
		assertFalse(plugin.tradeActive);
		assertNull(plugin.pendingTradeFrame.get());
	}

	@Test
	public void malformedTokenNeverUploads() throws Exception
	{
		// A token that is present but MALFORMED must be treated as unlinked: the commit path stops at
		// the token guard, before touching the (null) executor/okHttpClient — an upload attempt would
		// NPE and fail the test. This is the arm that matters now that the token is the only gate: a
		// gate keyed on "is the string non-empty" rather than on the ^[a-f0-9]{32}$ shape would pass
		// every other test in this file and fail here.
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", new AccountConnectConfig()
		{
			@Override public boolean enableUpload() { return true; }

			@Override
			public String linkToken()
			{
				return "not-a-valid-token";	// fails ^[a-f0-9]{32}$
			}
		});
		plugin.tradeActive = true;
		plugin.pendingTradeFrame.set(syntheticFrame(8, 8));

		plugin.handleTradeChat("Accepted trade.");
		assertNull(plugin.pendingTradeFrame.get());
		assertFalse(plugin.tradeActive);
	}

	// ---- helpers ----

	/** LINKED, ARMED (frame buffered), but no executor/okHttpClient: any upload attempt would NPE. */
	private static AccountConnectPlugin armedPluginWithoutNetwork() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", enabledConfig(null));
		plugin.tradeActive = true;
		plugin.tradeArmed = true;
		plugin.pendingTradeFrame.set(syntheticFrame(8, 8));
		return plugin;
	}

	private static AccountConnectConfig enabledConfig(String baseUrl)
	{
		return new AccountConnectConfig()
		{
			@Override public boolean enableUpload() { return true; }

			@Override
			public String linkToken()
			{
				return TEST_TOKEN;	// the token IS the gate now (the opt-in toggle was removed 2026-09-02)
			}

			@Override
			public String apiBaseUrl()
			{
				return baseUrl != null ? baseUrl : AccountConnectConfig.super.apiBaseUrl();
			}
		};
	}

	private static BufferedImage syntheticFrame(int w, int h)
	{
		BufferedImage img = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setColor(Color.RED);
		g.fillRect(0, 0, w, h);
		g.setColor(Color.GREEN);
		g.fillRect(0, 0, w / 2, h / 2);
		g.dispose();
		return img;
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private static byte[] readAll(InputStream in) throws java.io.IOException
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		byte[] chunk = new byte[8192];
		int n;
		while ((n = in.read(chunk)) != -1)
		{
			out.write(chunk, 0, n);
		}
		return out.toByteArray();
	}

	private static boolean startsWith(byte[] data, byte[] prefix)
	{
		if (data.length < prefix.length)
		{
			return false;
		}
		for (int i = 0; i < prefix.length; i++)
		{
			if (data[i] != prefix[i])
			{
				return false;
			}
		}
		return true;
	}

	private static int indexOf(byte[] haystack, byte[] needle)
	{
		outer:
		for (int i = 0; i <= haystack.length - needle.length; i++)
		{
			for (int j = 0; j < needle.length; j++)
			{
				if (haystack[i + j] != needle[j])
				{
					continue outer;
				}
			}
			return i;
		}
		return -1;
	}

	private static final class Capture
	{
		final String path;
		final String contentType;
		final byte[] body;

		Capture(String path, String contentType, byte[] body)
		{
			this.path = path;
			this.contentType = contentType;
			this.body = body;
		}
	}
}

package com.osrsbestinslot.export;

import java.io.File;
import java.lang.reflect.Field;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.fail;

/**
 * Drift gate for the PLUGIN_VERSION constant. The plugin stamps PLUGIN_VERSION into every snapshot's
 * source.plugin_version, which is how osrsbestinslot.com tells which build an account is running. That
 * constant and build.gradle's project version are two hand-edited places, so they can silently diverge
 * (they did: the constant was "0.5.0" while the build shipped 0.6.0). This test parses build.gradle's
 * version and asserts the constant equals it, turning any future drift into a build failure — you can
 * no longer bump one without the other. It fails loud (not silently) if build.gradle can't be found or
 * the version line can't be uniquely located.
 */
public class VersionDriftTest
{
	@Test
	public void pluginVersionConstantMatchesBuildGradle() throws Exception
	{
		String buildVersion = parseBuildGradleVersion();
		String pluginVersion = readPluginVersionConstant();
		assertEquals(
			"PLUGIN_VERSION must equal build.gradle's version — bump both together",
			buildVersion, pluginVersion);
	}

	/** Read the private static final PLUGIN_VERSION reflectively (no need to widen production visibility). */
	private static String readPluginVersionConstant() throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField("PLUGIN_VERSION");
		f.setAccessible(true);
		Object value = f.get(null);
		assertNotNull("PLUGIN_VERSION must be set", value);
		return (String) value;
	}

	/**
	 * Extract the single top-level {@code version = '...'} assignment from build.gradle. Case-sensitive
	 * and line-anchored on purpose: it must not match {@code def runeLiteVersion = 'latest.release'}
	 * (capital V) nor a dependency map's {@code version: runeLiteVersion} (colon, unquoted). Fails if the
	 * file is missing or the assignment is absent / ambiguous, so the gate can never pass vacuously.
	 */
	private static String parseBuildGradleVersion() throws Exception
	{
		File gradle = locateBuildGradle();
		String text = new String(Files.readAllBytes(gradle.toPath()), StandardCharsets.UTF_8);
		Pattern p = Pattern.compile("(?m)^\\s*version\\s*=\\s*['\"]([^'\"]+)['\"]\\s*$");
		Matcher m = p.matcher(text);
		String found = null;
		int count = 0;
		while (m.find())
		{
			found = m.group(1);
			count++;
		}
		assertEquals("expected exactly one top-level version assignment in build.gradle", 1, count);
		return found;
	}

	/** build.gradle lives at the module root = the gradle test working directory; probe the usual spots. */
	private static File locateBuildGradle()
	{
		File[] candidates = {
			new File("build.gradle"),
			new File(System.getProperty("user.dir"), "build.gradle"),
		};
		for (File f : candidates)
		{
			if (f.isFile())
			{
				return f;
			}
		}
		fail("could not locate build.gradle (cwd=" + System.getProperty("user.dir") + ")");
		return null; // unreachable — fail() throws
	}
}

