	private static List<Map<String, Object>> itemList(int id, int qty)
	{
		List<Map<String, Object>> l = new ArrayList<>();
		Map<String, Object> m = new LinkedHashMap<>();
		m.put("id", id);
		m.put("qty", qty);
		l.add(m);
		return l;
	}

	private static void invokeReset(AccountConnectPlugin plugin) throws Exception
	{
		java.lang.reflect.Method m = AccountConnectPlugin.class.getDeclaredMethod("resetTradeState");
		m.setAccessible(true);
		m.invoke(plugin);
	}

	private static Object field(AccountConnectPlugin plugin, String name) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		return f.get(plugin);
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

package com.osrsbestinslot.export;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.google.gson.Gson;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import okhttp3.OkHttpClient;
import org.junit.Before;
import org.junit.Test;

/**
 * Regression guards for the two HIGH defects found by the 0.7.4 adversarial review. Both were
 * introduced BY 0.7.4 and neither was covered by the release's own tests — the suite was green while
 * both were live, which is why these exist.
 */
public class TradeLeakAndFlushWedgeTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";
	private static final int TRADE_MAIN_GROUP_ID = 335;

	private AccountConnectPlugin plugin;

	@Before
	public void setUp() throws Exception
	{
		plugin = new AccountConnectPlugin();
		inject("gson", new Gson());
		inject("okHttpClient", new OkHttpClient());
	}

	private void inject(String name, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private Object get(String name) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		return f.get(plugin);
	}

	private void configWith(String apiBaseUrl) throws Exception
	{
		AccountConnectConfig config = mock(AccountConnectConfig.class);
		when(config.enableUpload()).thenReturn(true);
		when(config.linkToken()).thenReturn(TOKEN);
		when(config.apiBaseUrl()).thenReturn(apiBaseUrl);
		inject("config", config);
	}

	// ============================================================ FINDING 1 — cross-trade leak

	/**
	 * A trade that ends WITHOUT acceptance must not leak its counterparty or received items into the
	 * next trade's event.
	 *
	 * <p>The leak path: a decline routes through handleTradeChat, which early-returns when trade
	 * screenshots are off — the DEFAULT — so resetTradeState() never runs. handleTradeWidgetClosed only
	 * resets when tradeArmed, which is set at confirm-load with screenshots ON, so a trade abandoned at
	 * the first screen never arms either. 0.7.4's last-non-empty-wins poll then PRESERVES the stale
	 * items past a next partner who offers nothing — the classic gold-delivery shape — producing
	 * {@code counterparty=Alice, received=[Bob's item]}.
	 *
	 * <p>0.7.3 could not do this: it assigned the pendings unconditionally at confirm, so every trade
	 * overwrote the last. The fix clears them at 335-load, the one point guaranteed to run per trade.
	 */
	@Test
	public void a335LoadClearsStalePendingsFromAnAbandonedTrade() throws Exception
	{
		configWith("https://example.invalid/api");

		// Trade 1 with Bob ended without acceptance — pendings survive in the real leak scenario.
		List<Map<String, Object>> bobsOffer = new ArrayList<>();
		Map<String, Object> bandos = new LinkedHashMap<>();
		bandos.put("id", 11832);
		bandos.put("qty", 1);
		bobsOffer.add(bandos);
		inject("pendingCounterparty", "Bob");
		inject("pendingTradeReceived", bobsOffer);
		inject("pendingReceivedText", "Bandos chestplate x 1");

		// Trade 2 opens. The 335-load must wipe Bob's residue before any polling happens.
		plugin.handleActivityWidgetLoaded(TRADE_MAIN_GROUP_ID);

		assertNull("counterparty from the abandoned trade must not survive", get("pendingCounterparty"));
		assertNull("received items must not survive — this is the field the release exists to fix",
			get("pendingTradeReceived"));
		assertNull("the text fallback must not survive either", get("pendingReceivedText"));
		assertTrue("polling must still be armed for the new trade", plugin.tradeMainOpen);
	}

	@Test
	public void repeatedAbandonedTradesNeverAccumulateResidue() throws Exception
	{
		configWith("https://example.invalid/api");
		for (int i = 0; i < 3; i++)
		{
			inject("pendingCounterparty", "Ghost" + i);
			List<Map<String, Object>> junk = new ArrayList<>();
			Map<String, Object> it = new LinkedHashMap<>();
			it.put("id", 4151 + i);
			it.put("qty", 1);
			junk.add(it);
			inject("pendingTradeReceived", junk);

			plugin.handleActivityWidgetLoaded(TRADE_MAIN_GROUP_ID);

			assertNull("each new trade starts clean", get("pendingCounterparty"));
			assertNull(get("pendingTradeReceived"));
		}
	}

	// ============================================================ FINDING 2 — permanent flush wedge

	/**
	 * A throw between draining the buffer and enqueueing the request must not lose the batch, and must
	 * NEVER leave delivery permanently wedged.
	 *
	 * <p>{@code apiBaseUrl} is user-editable and {@code Request.Builder.url()} throws
	 * IllegalArgumentException on a malformed value — a pasted non-URL is enough. Before the guard, that
	 * threw AFTER the buffer was cleared and {@code eventPostInFlight} set, so the batch was lost and
	 * every later flush early-returned forever, silently, with no further log lines. 0.7.3 recovered as
	 * soon as the user fixed the typo; unguarded 0.7.4 would stay dead until a plugin restart.
	 */
	@Test
	public void aMalformedApiUrlRequeuesTheBatchAndDoesNotWedgeDelivery() throws Exception
	{
		configWith("not a url at all");

		Map<String, Object> ev = new LinkedHashMap<>();
		ev.put("type", "trade");
		synchronized (plugin.pendingEvents)
		{
			plugin.pendingEvents.add(ev);
		}

		plugin.flushEvents();	// must not propagate

		synchronized (plugin.pendingEvents)
		{
			assertEquals("the batch must be preserved, not destroyed by the throw",
				1, plugin.pendingEvents.size());
		}
		assertFalse("the in-flight flag MUST be cleared, or every later flush early-returns forever",
			plugin.eventPostInFlight);
		assertTrue("the failure must arm the backoff like any other", plugin.eventRetryBackoffUntilMs > 0);
	}

	/**
	 * The recovery half: after the user CORRECTS the URL, delivery must resume. This is the difference
	 * between a transient config typo and a session-long silent outage.
	 */
	@Test
	public void deliveryResumesOnceTheUrlIsCorrected() throws Exception
	{
		configWith("not a url at all");
		Map<String, Object> ev = new LinkedHashMap<>();
		ev.put("type", "trade");
		synchronized (plugin.pendingEvents)
		{
			plugin.pendingEvents.add(ev);
		}
		plugin.flushEvents();
		assertFalse(plugin.eventPostInFlight);

		// User fixes the config; the next tick must actually attempt a send rather than early-return.
		configWith("http://127.0.0.1:1/api");	// refused connection, but a VALID url
		plugin.eventRetryBackoffUntilMs = 0L;
		plugin.flushEvents();

		// The batch left the buffer (a real attempt happened) or came back via onFailure — either way
		// the flag must not be stuck true, which is what "wedged" means.
		Thread.sleep(500);
		assertFalse("delivery must not be permanently wedged after a corrected config",
			plugin.eventPostInFlight);
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.events.GameTick;
import net.runelite.api.widgets.Widget;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Trade RECEIVED-side + counterparty capture from the MAIN trade screen (335) — the fix for the prod bug
 * where 0/745 trades carried a counterparty or itemised received[] because everything was read at the
 * CONFIRM screen (334), by which point the 335 title widget is gone and the confirm "You will receive"
 * column is a value-text summary that collapses to "Lots!".
 *
 * These tests prove the capture + buffering LOGIC against MOCKED widgets. They do NOT — and cannot —
 * prove the real runtime shape of Trademain.OTHER_OFFER (21954588): whether it exposes item children and
 * is populated when polled. That requires one live two-sided in-game trade (see the plan's verify step).
 */
public class TradeOtherOfferCaptureTest
{
	private static final String TEST_TOKEN = "0123456789abcdef0123456789abcdef";
	private static final int MAIN_OTHER_OFFER = 21954588;	// Trademain.OTHER_OFFER (other player's grid, 335)
	private static final int TRADE_TITLE = 21954591;		// Trademain.TITLE ("Trading With: X")
	private static final int CONFIRM_RECEIVE = 21889048;	// Tradeconfirm.YOU_WILL_RECEIVE (value-text, 334)
	private static final int TRADE_MAIN_GROUP = 335;
	private static final int TRADE_CONFIRM_GROUP = 334;

	private static AccountConnectConfig onConfig()
	{
		return new AccountConnectConfig()
		{
			@Override public boolean enableUpload() { return true; }

			@Override
			public String linkToken()
			{
				return TEST_TOKEN;
			}
		};
	}

	/** A widget with the given [id,qty] item children (root itself carries no item). */
	private static Widget gridOf(int[]... items)
	{
		Widget root = mock(Widget.class);
		when(root.getItemId()).thenReturn(-1);
		Widget[] kids = new Widget[items.length];
		for (int i = 0; i < items.length; i++)
		{
			Widget k = mock(Widget.class);
			when(k.getItemId()).thenReturn(items[i][0]);
			when(k.getItemQuantity()).thenReturn(items[i][1]);
			kids[i] = k;
		}
		when(root.getChildren()).thenReturn(kids);
		return root;
	}

	private static Widget titleOf(String text)
	{
		Widget w = mock(Widget.class);
		when(w.getText()).thenReturn(text);
		return w;
	}

	@Test
	public void capturesReceivedItemsAndCounterpartyFromMainScreen() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Client client = mock(Client.class);
		Widget grid = gridOf(new int[]{20997, 3}, new int[]{22486, 1});	// build BEFORE stubbing (gridOf uses when())
		Widget title = titleOf("Trading With: Snaauz");
		when(client.getWidget(MAIN_OTHER_OFFER)).thenReturn(grid);
		when(client.getWidget(TRADE_TITLE)).thenReturn(title);
		inject(plugin, "client", client);

		plugin.captureOtherOfferWhileMainOpen();

		@SuppressWarnings("unchecked")
		List<Map<String, Object>> recv = (List<Map<String, Object>>) field(plugin, "pendingTradeReceived");
		assertEquals(2, recv.size());
		assertEquals(20997, recv.get(0).get("id"));
		assertEquals(3, recv.get(0).get("qty"));
		assertEquals(22486, recv.get(1).get("id"));
		assertEquals("Snaauz", field(plugin, "pendingCounterparty"));
	}

	@Test
	public void gameTickPollsOnlyWhileMainScreenOpen() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Client client = mock(Client.class);
		Widget grid = gridOf(new int[]{995, 5000});
		Widget title = titleOf("Trading With: Bob");
		when(client.getWidget(MAIN_OTHER_OFFER)).thenReturn(grid);
		when(client.getWidget(TRADE_TITLE)).thenReturn(title);
		inject(plugin, "client", client);

		// tradeMainOpen == false → tick is a no-op
		plugin.onGameTick(mock(GameTick.class));
		assertNull("no capture while main screen closed", field(plugin, "pendingTradeReceived"));

		// tradeMainOpen == true → tick captures
		inject(plugin, "tradeMainOpen", true);
		plugin.onGameTick(mock(GameTick.class));
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> recv = (List<Map<String, Object>>) field(plugin, "pendingTradeReceived");
		assertEquals(1, recv.size());
		assertEquals(995, recv.get(0).get("id"));
	}

	@Test
	public void mainScreenCaptureNotOverwrittenByConfirmTextSummary() throws Exception
	{
		// Simulate: the 335 poll already captured the itemised other-offer + name. Then the confirm screen
		// (334) loads with only a "Lots!" text column. The confirm branch must NOT clobber the good capture.
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		inject(plugin, "tradeMainOpen", true);
		inject(plugin, "pendingTradeReceived", itemList(20997, 3));
		inject(plugin, "pendingCounterparty", "Snaauz");
		Client client = mock(Client.class);
		Widget textOnly = mock(Widget.class);
		when(textOnly.getItemId()).thenReturn(-1);
		when(textOnly.getText()).thenReturn("Lots!");
		when(client.getWidget(CONFIRM_RECEIVE)).thenReturn(textOnly);	// confirm value-text column
		when(client.getItemContainer(90)).thenReturn(null);				// own offer empty in this test
		inject(plugin, "client", client);

		plugin.handleActivityWidgetLoaded(TRADE_CONFIRM_GROUP);

		assertFalse("polling stopped at confirm", (boolean) field(plugin, "tradeMainOpen"));
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> recv = (List<Map<String, Object>>) field(plugin, "pendingTradeReceived");
		assertEquals("main-screen items preserved", 1, recv.size());
		assertEquals(20997, recv.get(0).get("id"));
		assertEquals("Snaauz", field(plugin, "pendingCounterparty"));
		assertNull("no text fallback when items already captured", field(plugin, "pendingReceivedText"));
	}

	@Test
	public void lastNonEmptyPollWins() throws Exception
	{
		// Offer starts empty (just opened), then the other player adds items, then (defensively) an empty
		// read must not wipe the captured offer.
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		inject(plugin, "tradeMainOpen", true);
		Client client = mock(Client.class);
		Widget title = titleOf("Trading With: Bob");
		Widget empty1 = gridOf();
		Widget full = gridOf(new int[]{11832, 1});
		Widget empty2 = gridOf();
		when(client.getWidget(TRADE_TITLE)).thenReturn(title);
		when(client.getWidget(MAIN_OTHER_OFFER))
			.thenReturn(empty1)   // 1st poll: empty offer
			.thenReturn(full)     // 2nd poll: bandos chestplate added
			.thenReturn(empty2);  // 3rd poll: transient empty read
		inject(plugin, "client", client);

		plugin.captureOtherOfferWhileMainOpen();
		assertNull("empty offer leaves buffer null", field(plugin, "pendingTradeReceived"));
		plugin.captureOtherOfferWhileMainOpen();
		plugin.captureOtherOfferWhileMainOpen();
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> recv = (List<Map<String, Object>>) field(plugin, "pendingTradeReceived");
		assertEquals("last NON-EMPTY read retained", 1, recv.size());
		assertEquals(11832, recv.get(0).get("id"));
	}

	@Test
	public void resetClearsTradeMainOpen() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "tradeMainOpen", true);
		java.lang.reflect.Method m = AccountConnectPlugin.class.getDeclaredMethod("resetTradeState");
		m.setAccessible(true);
		m.invoke(plugin);
		assertFalse((boolean) field(plugin, "tradeMainOpen"));
	}

	private static List<Map<String, Object>> itemList(int id, int qty)
	{
		List<Map<String, Object>> l = new ArrayList<>();
		Map<String, Object> mm = new java.util.LinkedHashMap<>();
		mm.put("id", id);
		mm.put("qty", qty);
		l.add(mm);
		return l;
	}

	private static Object field(AccountConnectPlugin plugin, String name) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		return f.get(plugin);
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Store-transfer counterparty capture — nearby[] (players seen over a shop visit), world, loc attached to
 * store events. Unmasks the untracked receiver of the general-store method: a seller lists an item cheap into
 * the shared store, an untracked player standing there buys it out (no trade event). The receiver is in the
 * nearby set — presence + persistence + proximity finger them. Logic proven against mocked players; real
 * WorldView timing is field-verified on a live shop visit.
 */
public class StoreNearbyCaptureTest
{
	private static final String TEST_TOKEN = "0123456789abcdef0123456789abcdef";

	private static AccountConnectConfig onConfig()
	{
		return new AccountConnectConfig()
		{
			@Override public boolean enableUpload() { return true; }

			@Override
			public String linkToken()
			{
				return TEST_TOKEN;
			}
		};
	}

	private static Player player(String name, int x, int y, int cb)
	{
		Player p = mock(Player.class);
		when(p.getName()).thenReturn(name);
		when(p.getWorldLocation()).thenReturn(new WorldPoint(x, y, 0));
		when(p.getCombatLevel()).thenReturn(cb);
		return p;
	}

	/** plugin wired to a client at self-loc, given nearby players list + world + tick. */
	private static AccountConnectPlugin plugin(Player self, List<Player> players, int world, int tick) throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Client client = mock(Client.class);
		when(client.getLocalPlayer()).thenReturn(self);
		when(client.getPlayers()).thenReturn(players);
		when(client.getWorld()).thenReturn(world);
		when(client.getTickCount()).thenReturn(tick);
		inject(plugin, "client", client);
		return plugin;
	}

	@Test
	public void accumulateTracksClosestApproachAndPersistence() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		Player b = mock(Player.class);
		when(b.getName()).thenReturn("Receiver");
		when(b.getCombatLevel()).thenReturn(126);
		Client client = mock(Client.class);
		when(client.getLocalPlayer()).thenReturn(self);
		List<Player> players = new ArrayList<>();
		players.add(self);
		players.add(b);
		when(client.getPlayers()).thenReturn(players);

		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		inject(plugin, "client", client);

		// tick 10: Receiver 3 tiles east
		when(b.getWorldLocation()).thenReturn(new WorldPoint(3167, 3486, 0));
		when(client.getTickCount()).thenReturn(10);
		plugin.accumulateShopNearby();
		// tick 13: Receiver steps adjacent (1 tile)
		when(b.getWorldLocation()).thenReturn(new WorldPoint(3165, 3486, 0));
		when(client.getTickCount()).thenReturn(13);
		plugin.accumulateShopNearby();

		@SuppressWarnings("unchecked")
		Map<String, int[]> seen = (Map<String, int[]>) field(plugin, "shopVisitNearby");
		int[] rec = seen.get("Receiver");
		assertEquals("closest approach kept", 1, rec[0]);
		assertEquals("first tick", 10, rec[1]);
		assertEquals("last tick", 13, rec[2]);
		assertEquals("combat level", 126, rec[3]);
	}

	@Test
	public void storeContextAttachesNearbyWorldLocNearestFirst() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		Player near = player("Adjacent", 3165, 3486, 100);	// dist 1
		Player far = player("Bystander", 3170, 3486, 50);	// dist 6
		List<Player> players = new ArrayList<>();
		players.add(self);
		players.add(far);
		players.add(near);
		AccountConnectPlugin plugin = plugin(self, players, 302, 20);

		plugin.accumulateShopNearby();		// build the visit set
		Map<String, Object> fields = new java.util.LinkedHashMap<>();
		plugin.addStoreContextFields(fields);

		assertEquals(302, fields.get("world"));
		assertEquals(java.util.Arrays.asList(3164, 3486, 0), fields.get("loc"));
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> nearby = (List<Map<String, Object>>) fields.get("nearby");
		assertEquals(2, nearby.size());
		assertEquals("nearest first", "Adjacent", nearby.get(0).get("rsn"));
		assertEquals(1, nearby.get(0).get("dist"));
		assertEquals("Bystander", nearby.get(1).get("rsn"));
		assertEquals(6, nearby.get(1).get("dist"));
	}

	@Test
	public void selfAndNamelessExcluded() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		Player nameless = mock(Player.class);
		when(nameless.getName()).thenReturn(null);
		when(nameless.getWorldLocation()).thenReturn(new WorldPoint(3165, 3486, 0));
		List<Player> players = new ArrayList<>();
		players.add(self);		// self must be excluded
		players.add(nameless);	// unnamed (rendering) player excluded
		AccountConnectPlugin plugin = plugin(self, players, 302, 5);

		plugin.accumulateShopNearby();
		@SuppressWarnings("unchecked")
		Map<String, int[]> seen = (Map<String, int[]>) field(plugin, "shopVisitNearby");
		assertTrue("no self, no nameless", seen.isEmpty());
	}

	@Test
	public void liveSnapshotBackfillsWhenAccumulatorEmpty() throws Exception
	{
		// store event fires before any tick accumulated -> nearby[] falls back to a live snapshot.
		Player self = player("Seller", 3164, 3486, 90);
		Player near = player("Walker", 3166, 3486, 70);	// dist 2
		List<Player> players = new ArrayList<>();
		players.add(self);
		players.add(near);
		AccountConnectPlugin plugin = plugin(self, players, 308, 1);

		Map<String, Object> fields = new java.util.LinkedHashMap<>();
		plugin.addStoreContextFields(fields);	// no accumulate() first

		@SuppressWarnings("unchecked")
		List<Map<String, Object>> nearby = (List<Map<String, Object>>) fields.get("nearby");
		assertEquals(1, nearby.size());
		assertEquals("Walker", nearby.get(0).get("rsn"));
		assertEquals(2, nearby.get(0).get("dist"));
		assertEquals("live snapshot carries offsets", 2, nearby.get(0).get("dx"));
	}

	@Test
	public void noPlayersNoNearbyStillCarriesWorldLoc() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		List<Player> players = new ArrayList<>();
		players.add(self);
		AccountConnectPlugin plugin = plugin(self, players, 302, 5);

		Map<String, Object> fields = new java.util.LinkedHashMap<>();
		plugin.addStoreContextFields(fields);

		assertNull("no nearby field when nobody around", fields.get("nearby"));
		assertEquals(302, fields.get("world"));
		assertFalse("world/loc still present", fields.isEmpty());
	}

	// ---- nearby_at_tx: the TRANSACTION-MOMENT snapshot (was completely untested until 2026-09-03) ----

	/**
	 * nearby_at_tx is the whole point of the field: nearby[] is everyone seen across the WHOLE visit,
	 * which over a long visit accumulates passers-by. nearby_at_tx is who was standing there at the
	 * instant the item moved. On production the two differ on roughly 1 event in 10, and the narrower
	 * list is the one that names a receiver — so a bug that made them identical would destroy the
	 * feature's value while every existing assertion still passed.
	 */
	@Test
	public void nearbyAtTxIsTheTransactionMomentNotTheWholeVisit() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		Player receiver = player("Receiver", 3164, 3486, 126);
		Player passerby = player("PasserBy", 3170, 3490, 60);

		// Visit accumulator saw BOTH — receiver and a passer-by who has since walked off.
		AccountConnectPlugin plugin = plugin(self, java.util.Arrays.asList(self, receiver), 311, 100);
		java.util.Map<String, int[]> visit = new java.util.LinkedHashMap<>();
		visit.put("Receiver", new int[]{0, 90, 100, 126});
		visit.put("PasserBy", new int[]{6, 90, 92, 60});
		inject(plugin, "shopVisitNearby", visit);

		// At the transaction moment only the receiver is present.
		inject(plugin, "nearbyAtTx", plugin.nearbyPlayersSnapshot(24));

		java.util.Map<String, Object> fields = new java.util.LinkedHashMap<>();
		plugin.addStoreContextFields(fields);

		@SuppressWarnings("unchecked")
		List<Map<String, Object>> visitWide = (List<Map<String, Object>>) fields.get("nearby");
		@SuppressWarnings("unchecked")
		List<Map<String, Object>> atTx = (List<Map<String, Object>>) fields.get("nearby_at_tx");

		assertNotNull("nearby_at_tx must be attached when a snapshot was taken", atTx);
		assertEquals("the visit-wide list keeps everyone seen", 2, visitWide.size());
		assertEquals("the transaction-moment list holds only who was there then", 1, atTx.size());
		assertEquals("Receiver", atTx.get(0).get("rsn"));
	}

	/**
	 * The field must be CONSUMED, not left set. It is a per-transaction snapshot, so a stale value
	 * leaking into the next store event would attach the previous transaction's bystanders to it —
	 * the exact shape of a false accusation.
	 */
	@Test
	public void nearbyAtTxIsClearedAfterItIsAttached() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		Player other = player("Other", 3164, 3486, 100);
		AccountConnectPlugin plugin = plugin(self, java.util.Arrays.asList(self, other), 311, 100);
		inject(plugin, "nearbyAtTx", plugin.nearbyPlayersSnapshot(24));

		java.util.Map<String, Object> first = new java.util.LinkedHashMap<>();
		plugin.addStoreContextFields(first);
		assertNotNull("first event carries the snapshot", first.get("nearby_at_tx"));

		java.util.Map<String, Object> second = new java.util.LinkedHashMap<>();
		plugin.addStoreContextFields(second);
		assertNull("a second event must NOT inherit the previous transaction's snapshot",
			second.get("nearby_at_tx"));
	}

	// ---- store_taken: the shop-stock counterparty inference (was completely untested) ----

	/**
	 * store_taken fires when the stock of an item THIS VISIT SOLD falls — someone bought it out of the
	 * dead drop. Only sold items are watched, because our own BUY also lowers stock and must never be
	 * reported as a taker.
	 */
	@Test
	public void storeTakenFiresOnlyForItemsThisVisitSold() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		Player taker = player("Taker", 3164, 3486, 126);
		AccountConnectPlugin plugin = plugin(self, java.util.Arrays.asList(self, taker), 412, 200);

		java.util.Set<Integer> sold = new java.util.LinkedHashSet<>();
		sold.add(20997);						// we sold this
		inject(plugin, "soldThisVisit", sold);
		java.util.Map<Integer, Integer> baseline = new java.util.LinkedHashMap<>();
		baseline.put(20997, 1);					// our item, stock 1
		baseline.put(29415, 43);				// an unrelated shop item
		inject(plugin, "shopStock", baseline);

		// Both fall: ours to 0 (a taker), the unrelated one to 42 (nothing to do with us).
		plugin.handleShopStockChanged(shopWith(new int[][]{{29415, 42}}));

		List<Map<String, Object>> events = plugin.pendingEvents;
		long taken = events.stream().filter(e -> "store_taken".equals(e.get("type"))).count();
		assertEquals("exactly one store_taken, for the SOLD item only", 1, taken);
		Map<String, Object> ev = events.stream()
			.filter(e -> "store_taken".equals(e.get("type"))).findFirst().orElseThrow(AssertionError::new);
		assertEquals(20997, ev.get("item"));
		assertEquals("stock fell by one", 1, ev.get("qty"));
	}

	/**
	 * The candidate list is EVIDENCE, not an accusation, and the code is careful to call it
	 * taken_by_candidates. An empty shop must therefore emit the event with NO candidate list at all
	 * rather than an empty one — "we do not know who" must not read as "nobody".
	 */
	@Test
	public void storeTakenOmitsCandidatesWhenNobodyIsPresent() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		AccountConnectPlugin plugin = plugin(self, java.util.Arrays.asList(self), 602, 200);

		java.util.Set<Integer> sold = new java.util.LinkedHashSet<>();
		sold.add(29415);
		inject(plugin, "soldThisVisit", sold);
		java.util.Map<Integer, Integer> baseline = new java.util.LinkedHashMap<>();
		baseline.put(29415, 43);
		inject(plugin, "shopStock", baseline);

		plugin.handleShopStockChanged(shopWith(new int[][]{{29415, 42}}));

		Map<String, Object> ev = plugin.pendingEvents.stream()
			.filter(e -> "store_taken".equals(e.get("type"))).findFirst().orElseThrow(AssertionError::new);
		assertNull("an empty shop must omit the candidate list, never emit an empty one",
			ev.get("taken_by_candidates"));
		assertEquals("the stock movement is still recorded", 29415, ev.get("item"));
	}

	/**
	 * OUR OWN BUY-BACK IS NOT A CUSTOMER (fixed 2026-09-03, found in field testing).
	 *
	 * The seller's own procedure has an explicit emergency step: if the customer cannot buy the item in time,
	 * the seller buys it back. That purchase lowers the shop stock exactly like a customer's, so the
	 * inference named a bystander as the taker. Measured on live events 3914798/3914799: a buy-back
	 * and a store_taken landed in the same second, and the plugin still named a candidate.
	 *
	 * A false counterparty is the worst output this feature can produce — it is evidence that could
	 * reach a dispute.
	 */
	@Test
	public void ourOwnBuybackIsNotReportedAsATaker() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		Player bystander = player("Bystander", 3164, 3486, 126);
		AccountConnectPlugin plugin = plugin(self, java.util.Arrays.asList(self, bystander), 412, 200);

		java.util.Set<Integer> sold = new java.util.LinkedHashSet<>();
		sold.add(20997);
		inject(plugin, "soldThisVisit", sold);
		java.util.Map<Integer, Integer> baseline = new java.util.LinkedHashMap<>();
		baseline.put(20997, 1);
		inject(plugin, "shopStock", baseline);

		// We just bought it back ourselves.
		inject(plugin, "lastSelfBuyItem", 20997);
		inject(plugin, "lastSelfBuyAtMs", System.currentTimeMillis());

		plugin.handleShopStockChanged(shopWith(new int[][]{}));

		assertTrue("a self buy-back must emit NO store_taken at all",
			plugin.pendingEvents.stream().noneMatch(e -> "store_taken".equals(e.get("type"))));
	}

	/** The suppression is time-boxed: an OLD self-buy must not mask a later genuine customer. */
	@Test
	public void anOldSelfBuyDoesNotMaskALaterCustomer() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		Player taker = player("Taker", 3164, 3486, 126);
		AccountConnectPlugin plugin = plugin(self, java.util.Arrays.asList(self, taker), 412, 200);

		java.util.Set<Integer> sold = new java.util.LinkedHashSet<>();
		sold.add(20997);
		inject(plugin, "soldThisVisit", sold);
		java.util.Map<Integer, Integer> baseline = new java.util.LinkedHashMap<>();
		baseline.put(20997, 1);
		inject(plugin, "shopStock", baseline);

		inject(plugin, "lastSelfBuyItem", 20997);
		inject(plugin, "lastSelfBuyAtMs", System.currentTimeMillis() - 60_000L);	// a minute ago

		plugin.handleShopStockChanged(shopWith(new int[][]{}));

		assertTrue("a stale self-buy must not suppress a real taker",
			plugin.pendingEvents.stream().anyMatch(e -> "store_taken".equals(e.get("type"))));
	}

	/** A stock RISE (the shop's own restock timer) is not someone taking our item. */
	@Test
	public void storeTakenIgnoresRestock() throws Exception
	{
		Player self = player("Seller", 3164, 3486, 90);
		AccountConnectPlugin plugin = plugin(self, java.util.Arrays.asList(self), 412, 200);

		java.util.Set<Integer> sold = new java.util.LinkedHashSet<>();
		sold.add(20997);
		inject(plugin, "soldThisVisit", sold);
		java.util.Map<Integer, Integer> baseline = new java.util.LinkedHashMap<>();
		baseline.put(20997, 1);
		inject(plugin, "shopStock", baseline);

		plugin.handleShopStockChanged(shopWith(new int[][]{{20997, 5}}));	// stock ROSE

		assertTrue("a stock rise must emit nothing",
			plugin.pendingEvents.stream().noneMatch(e -> "store_taken".equals(e.get("type"))));
	}

	/**
	 * Build a shop container holding the given {itemId, qty} pairs.
	 *
	 * net.runelite.api.Item is FINAL, so Mockito cannot mock it — construct real ones. (The mock
	 * version of this helper failed with "Cannot mock/spy because - final class", 2026-09-03.)
	 */
	private static net.runelite.api.ItemContainer shopWith(int[][] pairs)
	{
		net.runelite.api.ItemContainer c = mock(net.runelite.api.ItemContainer.class);
		net.runelite.api.Item[] items = new net.runelite.api.Item[pairs.length];
		for (int i = 0; i < pairs.length; i++)
		{
			items[i] = new net.runelite.api.Item(pairs[i][0], pairs[i][1]);
		}
		when(c.getItems()).thenReturn(items);
		return c;
	}

	private static Object field(AccountConnectPlugin plugin, String name) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		return f.get(plugin);
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

package com.osrsbestinslot.export;

import java.awt.image.BufferedImage;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * THE GATE, as one place. These overlays render other players' names on screen, so the
 * question "could an ordinary player ever see this?" must have exactly one answer: no.
 *
 * Three independent conditions, ALL required: a linked token, the backend grant, and an open shop.
 * The grant itself is server-derived from the RSN allowlist and cannot be self-issued —
 * tests/e3a/store-tools-gate.test.mjs holds that half.
 */
public class StoreToolsGateTest
{
	private static java.awt.Graphics2D g()
	{
		return new BufferedImage(300, 200, BufferedImage.TYPE_INT_ARGB).createGraphics();
	}

	private static AccountConnectPlugin withToken(String token) throws Exception
	{
		return withTokenAndSwitch(token, true);
	}

	private static AccountConnectPlugin withTokenAndSwitch(String token, boolean upload) throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		java.lang.reflect.Field f = AccountConnectPlugin.class.getDeclaredField("config");
		f.setAccessible(true);
		f.set(p, new AccountConnectConfig()
		{
			@Override
			public boolean enableUpload()
			{
				return upload;
			}

			@Override
			public String linkToken()
			{
				return token;
			}
		});
		return p;
	}

	@Test
	public void aFreshPluginGrantsNothing() throws Exception
	{
		System.clearProperty("osrsbis.storetools");
		assertFalse("default must be closed", withToken("0123456789abcdef0123456789abcdef").storeToolsEnabled());
	}

	/** No token means no account is linked at all — the grant cannot apply to anybody. */
	@Test
	public void noLinkedTokenMeansNoOverlaysEvenWithTheGrant() throws Exception
	{
		for (String bad : new String[]{"", "   ", "not-a-token", "0123456789abcdef"})
		{
			AccountConnectPlugin p = withToken(bad);
			p.setStoreToolsForTest(true);
			assertFalse("token '" + bad + "' must not enable store tools", p.storeToolsEnabled());
		}
	}

	/** BOTH overlays must obey the gate. One of them leaking is the whole failure. */
	@Test
	public void neitherOverlayDrawsWithoutTheGrant() throws Exception
	{
		AccountConnectPlugin p = withToken("0123456789abcdef0123456789abcdef");
		p.setShopOpenForTest(true);		// shop open, grant withheld
		assertNull("reset overlay must stay hidden", new StoreResetOverlay(p).render(g()));
		assertNull("nearby overlay must stay hidden", new StoreNearbyOverlay(p).render(g()));
	}

	/** And with the grant, both draw — otherwise the gate is just "always off". */
	@Test
	public void bothOverlaysDrawWhenGrantedInsideAShop() throws Exception
	{
		AccountConnectPlugin p = withToken("0123456789abcdef0123456789abcdef");
		p.setShopOpenForTest(true);
		p.setStoreToolsForTest(true);
		org.junit.Assert.assertNotNull(new StoreResetOverlay(p).render(g()));
		org.junit.Assert.assertNotNull(new StoreNearbyOverlay(p).render(g()));
	}

	/** Outside a shop, a granted account still sees nothing. */
	@Test
	public void theGrantDoesNotFollowTheUserOutOfTheShop() throws Exception
	{
		AccountConnectPlugin p = withToken("0123456789abcdef0123456789abcdef");
		p.setStoreToolsForTest(true);		// granted, but no shop open
		assertNull(new StoreResetOverlay(p).render(g()));
		assertNull(new StoreNearbyOverlay(p).render(g()));
	}

	/**
	 * THE SHIPPED BUILD HAS NO LOCAL WAY IN. The dev override is a JVM system property, which the
	 * Plugin Hub launcher never sets — but a config item or an env read WOULD be reachable by a
	 * player, so assert the override's shape rather than trusting the comment above it.
	 */
	@Test
	public void theOverrideIsAJvmPropertyAndNothingElse() throws Exception
	{
		System.clearProperty("osrsbis.storetools");
		assertFalse(AccountConnectPlugin.storeToolsDevOverride());
		try
		{
			System.setProperty("osrsbis.storetools", "on");
			assertTrue(AccountConnectPlugin.storeToolsDevOverride());
		}
		finally
		{
			System.clearProperty("osrsbis.storetools");
		}
		// A player-reachable surface would be a config key. There must be none.
		for (java.lang.reflect.Method m : AccountConnectConfig.class.getMethods())
		{
			assertFalse("config must expose no store-tools switch: " + m.getName(),
				m.getName().toLowerCase().contains("storetool"));
		}
	}

	/**
	 * THE UPLOAD SWITCH GATES THE OVERLAYS TOO (F3).
	 *
	 * These overlays are the visible half of a feature whose data half is uploaded, and the grant
	 * that turns them on arrives on an upload response. A user who turned the upload switch off has
	 * declined the feature, so drawing the countdown and the nearby panel at them shows a feature
	 * they said no to. The gate now calls uploadAllowed(), which is the same gate every network send
	 * uses and which subsumes the linked-token requirement this gate carried before.
	 */
	@Test
	public void theUploadSwitchOffMeansNoOverlaysEvenWithTheGrant() throws Exception
	{
		AccountConnectPlugin p =
			withTokenAndSwitch("0123456789abcdef0123456789abcdef", false);
		p.setStoreToolsForTest(true);
		p.setShopOpenForTest(true);

		assertFalse("the upload switch off must close the store-tools gate", p.storeToolsEnabled());
		assertNull("reset overlay must stay hidden", new StoreResetOverlay(p).render(g()));
		assertNull("nearby overlay must stay hidden", new StoreNearbyOverlay(p).render(g()));
	}

	/** The same, through the dev override — the override grants the feature, never the consent. */
	@Test
	public void theDevOverrideDoesNotBypassTheUploadSwitch() throws Exception
	{
		AccountConnectPlugin p =
			withTokenAndSwitch("0123456789abcdef0123456789abcdef", false);
		p.setShopOpenForTest(true);
		try
		{
			System.setProperty("osrsbis.storetools", "on");
			assertFalse("the override must not bypass the upload switch", p.storeToolsEnabled());
			assertNull(new StoreResetOverlay(p).render(g()));
			assertNull(new StoreNearbyOverlay(p).render(g()));
		}
		finally
		{
			System.clearProperty("osrsbis.storetools");
		}
	}

	/** And with the switch back on, the same granted account draws — the gate is not "always off". */
	@Test
	public void theUploadSwitchOnRestoresTheOverlays() throws Exception
	{
		AccountConnectPlugin p =
			withTokenAndSwitch("0123456789abcdef0123456789abcdef", true);
		p.setStoreToolsForTest(true);
		p.setShopOpenForTest(true);

		assertTrue(p.storeToolsEnabled());
		org.junit.Assert.assertNotNull(new StoreResetOverlay(p).render(g()));
		org.junit.Assert.assertNotNull(new StoreNearbyOverlay(p).render(g()));
	}

	/** A server revoke mid-session closes the gate immediately. */
	@Test
	public void aRevokeClosesTheGate() throws Exception
	{
		AccountConnectPlugin p = withToken("0123456789abcdef0123456789abcdef");
		p.setStoreToolsForTest(true);
		p.setShopOpenForTest(true);
		assertTrue(p.storeToolsEnabled());
		p.setStoreToolsForTest(false);
		assertFalse("revoke must take effect at once", p.storeToolsEnabled());
		assertNull(new StoreNearbyOverlay(p).render(g()));
	}
}

package com.osrsbestinslot.export;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.lang.reflect.Field;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for the store delivery-proof burst capture path (Task B2) — no live client needed.
 * Covers: the opt-in default (off), the server force-disable gate, wall-clock 1-in-time decimation,
 * and the RGB (no-alpha) frame conversion the JDK JPEG writer requires. The listener wiring, real
 * shop-widget event delivery, and the multipart upload (B3) need a live client / are covered elsewhere.
 */
public class StoreClipCaptureTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";

	/** Config with a linked token — the ONLY local condition for capture since the toggle was removed. */
	private static AccountConnectConfig linked()
	{
		return new AccountConnectConfig()
		{
			@Override public boolean enableUpload() { return true; }

			@Override
			public String linkToken()
			{
				return TOKEN;
			}
		};
	}

	// (a) no link token -> no capture. The separate opt-in toggle was removed 2026-09-02; capture is now
	// part of core sync, so the token IS the gate. An unlinked client must still capture nothing.
	@Test
	public void storeClipsDisabledWithoutLinkToken() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", new AccountConnectConfig() {
			@Override public boolean enableUpload() { return true; }
});
		assertFalse("store-clip capture must be off with no link token",
			plugin.storeClipsEnabled());
	}

	// (a2) a malformed token is not a link — same refusal as none at all.
	@Test
	public void storeClipsDisabledOnMalformedToken() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", new AccountConnectConfig()
		{
			@Override public boolean enableUpload() { return true; }

			@Override
			public String linkToken()
			{
				return "not-a-token";
			}
		});
		assertFalse("a malformed token must not enable capture", plugin.storeClipsEnabled());
	}

	// (b) server force-disable wins even when the client IS linked.
	@Test
	public void serverForceDisableOverridesLinkedToken() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", linked());
		// linked, server not disabling -> enabled.
		assertTrue("a linked token with no server disable must enable capture",
			plugin.storeClipsEnabled());
		// server flips it off -> gate closes despite the link.
		plugin.serverClipsDisabled = true;
		assertFalse("server X-Clips=off must force capture off",
			plugin.storeClipsEnabled());
	}

	// (c) wall-clock decimation: 50 render frames across one simulated second -> exactly CLIP_FPS samples.
	//
	// The expectation is DERIVED from CLIP_FPS, not hardcoded. It used to assert a literal 1, so raising
	// the sample rate to 2 on 2026-09-02 turned this red for the rate change rather than for a defect —
	// a test that fails when the thing it measures is deliberately changed is testing the constant, not
	// the decimation. What must hold at ANY rate is: exactly CLIP_FPS samples per second, and the same
	// again in the following second (a rate, never a one-shot).
	@Test
	public void wallClockDecimationYieldsOneSamplePerSecond()
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		// nextClipSampleAt defaults to 0; walk 50 evenly-spaced nanoTime ticks over exactly one second
		// (~50fps render). Only every (1/CLIP_FPS)s boundary should cross the gate.
		long oneSecond = 1_000_000_000L;
		int trues = 0;
		for (int i = 0; i < 50; i++)
		{
			long now = i * (oneSecond / 50);	// 0ms, 20ms, ... 980ms
			if (plugin.shouldSampleClipFrame(now))
			{
				trues++;
			}
		}
		// Exact equality is the WRONG assertion above 1fps and asserting it hid a real property. The gate
		// advances by exactly 1/CLIP_FPS seconds, but render ticks land on a 20ms grid, so each sample
		// fires at the first tick AT OR AFTER its boundary and the remainder carries into the next
		// second: at 8fps a 50-tick second yields 8 then 7, alternating, averaging 8. That is correct
		// decimation, not drift — the gate never loses time, it only rounds each sample forward. So the
		// per-second count is asserted within +/-1 and the TWO-second total is asserted exactly, which
		// is what actually proves the rate.
		assertTrue("expected ~CLIP_FPS samples across one simulated second, got " + trues,
			Math.abs(trues - AccountConnectPlugin.CLIP_FPS) <= 1);
		// MOUSE VISIBILITY is the floor, not "enough to catch the transaction". A cursor crossing a shop
		// interface reads as movement only when consecutive frames are ~125ms apart; 3fps (333ms) was
		// rejected on review as too laggy to see the mouse at all. Asserted independently of whatever
		// CLIP_FPS currently is, so lowering the rate for a byte saving turns this RED.
		assertTrue("a delivery clip must sample at the client's own render rate (30fps) to read as motion",
			AccountConnectPlugin.CLIP_FPS >= 30);
		// The burst must fit the SERVER's frame-count cap. This is 240 only because the ingest cap was
		// raised to 360 in the same change (osrsbis-web-integrator backend.js FRAMES_COUNT_MAX); with the
		// old 120 the server 400s the whole burst — it does not trim it — so this number and the server's
		// must move together, and this assertion is what catches them drifting apart.
		// The visit's frames no longer have to fit ONE request: the upload is chunked. What must hold is
		// that a CHUNK fits the smallest server frame cap ever deployed (120), with margin. This is the
		// assertion that lets clip length grow without a server deploy — and that turns red if someone
		// raises the chunk size back up to the current cap and re-couples the two.
		assertTrue("a chunk must fit the smallest deployed server frame cap (120) with margin",
			AccountConnectPlugin.CLIP_CHUNK_FRAMES <= 100);
		assertTrue("chunking must actually chunk a full visit",
			AccountConnectPlugin.MAX_CLIP_FRAMES > AccountConnectPlugin.CLIP_CHUNK_FRAMES);
		// And it must fit the BYTE cap at the measured mean frame size (56KB over 68 real frames), or the
		// newest-suffix trim silently discards the opening of the visit.
		// 30KB is the MEASURED mean at the current MAX_FRAME_WIDTH/quality (704px, q0.55). If either is
		// raised, this arm goes red — which is the point: the frame size and the frame count are one
		// budget, and changing one without the other silently truncates the start of every visit.
		// This is the VISIT budget (memory + total upload), not a per-request limit.
		assertTrue("fps x seconds at ~30KB/frame (704px q0.55) must fit the 12MB visit budget",
			(long) AccountConnectPlugin.MAX_CLIP_FRAMES * 30 * 1024
				<= AccountConnectPlugin.MAX_CLIP_BURST_BYTES);
		assertEquals("frame width must stay at the legibility floor that the byte budget assumes",
			704, AccountConnectPlugin.MAX_FRAME_WIDTH);

		// A second simulated second must yield the next sample — proves it is a rate, not a one-shot.
		int trues2 = 0;
		for (int i = 50; i < 100; i++)
		{
			long now = i * (oneSecond / 50);	// 1000ms .. 1980ms
			if (plugin.shouldSampleClipFrame(now))
			{
				trues2++;
			}
		}
		assertTrue("expected ~CLIP_FPS more samples across the next simulated second, got " + trues2,
			Math.abs(trues2 - AccountConnectPlugin.CLIP_FPS) <= 1);
		// The two-second total is exact: rounding each sample forward must not COST a sample.
		assertEquals("two simulated seconds must yield exactly 2x CLIP_FPS samples",
			2 * AccountConnectPlugin.CLIP_FPS, trues + trues2);

		// Over a LONG span the rate must not drift. This is the arm that caught the real defect: the
		// gate used to advance from the observed tick, so each sample's rounding error compounded and
		// 8fps delivered ~7.5. Ten simulated seconds at a 50fps render must yield 10x CLIP_FPS.
		AccountConnectPlugin p2 = new AccountConnectPlugin();
		int over10s = 0;
		for (int i = 0; i < 500; i++)
		{
			if (p2.shouldSampleClipFrame(i * (oneSecond / 50)))
			{
				over10s++;
			}
		}
		assertEquals("ten simulated seconds must yield exactly 10x CLIP_FPS samples — no cumulative drift",
			10 * AccountConnectPlugin.CLIP_FPS, over10s);

		// A long stall must NOT produce a catch-up burst on consecutive frames: duplicating one instant
		// is not evidence. After a 5-second gap the next tick samples once, and the tick right after it
		// (20ms later, well inside the 125ms period) must not.
		AccountConnectPlugin p3 = new AccountConnectPlugin();
		assertTrue("first call always samples", p3.shouldSampleClipFrame(0L));
		assertTrue("the tick after a long stall samples once", p3.shouldSampleClipFrame(5 * oneSecond));
		assertFalse("...and does not fire again 20ms later",
			p3.shouldSampleClipFrame(5 * oneSecond + oneSecond / 50));
	}

	// (d) RGB conversion: an ARGB frame becomes TYPE_INT_RGB (the JDK JPEG writer corrupts ARGB rasters).
	@Test
	public void toRgbFrameProducesNonAlphaRgb()
	{
		BufferedImage argb = new BufferedImage(32, 24, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = argb.createGraphics();
		g.setColor(Color.ORANGE);
		g.fillRect(0, 0, 32, 24);
		g.dispose();

		BufferedImage rgb = AccountConnectPlugin.toRgbFrame(argb);
		assertNotNull("toRgbFrame returned null for a valid image", rgb);
		assertEquals("frame must be TYPE_INT_RGB (no alpha) for the JPEG writer",
			BufferedImage.TYPE_INT_RGB, rgb.getType());
		assertEquals("width must be preserved", 32, rgb.getWidth());
		assertEquals("height must be preserved", 24, rgb.getHeight());
	}

	/**
	 * WEDGE ARM (added 2026-09-02 after mutation testing): clipFramePending is a one-in-flight latch, so
	 * ANY path out of the frame callback must clear it. A DrawManager that hands back a null image — the
	 * documented shape when the GPU plugin owns the surface — must not leave the latch set, or capture
	 * silently stops for the rest of the visit after one bad frame and the clip is short or empty.
	 *
	 * Falsified: removing the `clipFramePending = false` from the null branch of onClipFrameTick makes
	 * this arm fail. Without it that mutation survived the whole suite.
	 */
	@Test
	public void nullFrameDoesNotWedgeCapture() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", linked());
		// A DrawManager whose listener is invoked immediately with a null image.
		inject(plugin, "drawManager", new net.runelite.client.ui.DrawManager()
		{
			@Override
			public void requestNextFrameListener(java.util.function.Consumer<java.awt.Image> consumer)
			{
				consumer.accept(null);
			}
		});
		inject(plugin, "clipCapturing", true);
		inject(plugin, "clipRing", new ClipRingBuffer(AccountConnectPlugin.MAX_CLIP_FRAMES));

		plugin.onClipFrameTick();		// first sample: null frame comes back
		assertFalse("a null frame must release the in-flight latch", pending(plugin));

		plugin.onClipFrameTick();		// a wedged latch would make this a no-op forever
		assertFalse("capture must still be able to request further frames", pending(plugin));
	}

	private static boolean pending(AccountConnectPlugin plugin) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField("clipFramePending");
		f.setAccessible(true);
		return f.getBoolean(plugin);
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
