	private static ItemContainer container(int... idQtyPairs)
	{
		ItemContainer c = mock(ItemContainer.class);
		Item[] items = new Item[idQtyPairs.length / 2];
		for (int i = 0; i < items.length; i++)
		{
			items[i] = new Item(idQtyPairs[i * 2], idQtyPairs[i * 2 + 1]);
		}
		when(c.getItems()).thenReturn(items);
		return c;
	}

	private static void inject(Object target, String field, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(target, value);
	}

	private static AccountConnectConfig onConfig()
	{
		return (AccountConnectConfig) java.lang.reflect.Proxy.newProxyInstance(
			AccountConnectConfig.class.getClassLoader(),
			new Class<?>[]{AccountConnectConfig.class},
			(proxy, method, args) -> {
				Class<?> rt = method.getReturnType();
				if (rt == boolean.class || rt == Boolean.class) { return Boolean.TRUE; }
				if (rt == String.class) { return "0123456789abcdef0123456789abcdef"; }
				if (rt == int.class || rt == Integer.class) { return 0; }
				return null;
			});
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The store reset clock (0.7.8).
 *
 * A general store cycles its stock on a fixed 60s clock. An item put into the shop vanishes at the
 * next tick of that clock, NOT 60s after it was sold — so an item sold 1s after a reset is gone in
 * 59s, and one sold at 58s is gone in 2. A seller currently feels this out by selling a junk item and
 * watching it disappear, which is a guess repeated by eye on every visit; measured over 56 real
 * sessions the gap between that probe and the first real item ran 5s to 146s.
 *
 * One observed reset fixes the PHASE, and every later reset follows from it while the shop stays
 * open (operator report, 2026-09-03). These arms hold the two properties that make the countdown safe to
 * trust: the arithmetic is a phase, not a per-item duration, and an UNKNOWN phase shows nothing
 * rather than a guess.
 */
public class StoreResetTimerTest
{
	private static final long P = 60_000L;

	// ---- phase arithmetic ----

	/**
	 * THE PROPERTY THE WHOLE FEATURE RESTS ON. Time remaining depends on where we are in the cycle,
	 * never on when an item was sold. A naive "60s from the sell" would pass a test that only ever
	 * measured from the anchor, so measure from three different offsets instead.
	 */
	@Test
	public void countdownIsAPhaseNotAPerItemDuration()
	{
		long anchor = 1_000_000L;
		assertEquals("1s after a reset -> 59s left", 59_000L, AccountConnectPlugin.msUntilNextReset(anchor, anchor + 1_000L));
		assertEquals("30s in -> 30s left", 30_000L, AccountConnectPlugin.msUntilNextReset(anchor, anchor + 30_000L));
		assertEquals("58s in -> 2s left", 2_000L, AccountConnectPlugin.msUntilNextReset(anchor, anchor + 58_000L));
	}

	/** The anchor keeps working across later cycles — one probe pins the phase for the whole visit. */
	@Test
	public void oneAnchorSurvivesManyCycles()
	{
		long anchor = 5_000_000L;
		assertEquals("into the 5th cycle, 40s elapsed", 20_000L,
			AccountConnectPlugin.msUntilNextReset(anchor, anchor + (4 * P) + 40_000L));
		assertEquals("an hour later the phase still holds", 45_000L,
			AccountConnectPlugin.msUntilNextReset(anchor, anchor + (60 * P) + 15_000L));
	}

	/** Landing exactly on a tick means a FULL period remains — never 0, which means "unknown". */
	@Test
	public void exactTickYieldsAFullPeriodNotZero()
	{
		long anchor = 2_000_000L;
		assertEquals(P, AccountConnectPlugin.msUntilNextReset(anchor, anchor));
		assertEquals(P, AccountConnectPlugin.msUntilNextReset(anchor, anchor + P));
		assertEquals(P, AccountConnectPlugin.msUntilNextReset(anchor, anchor + (7 * P)));
	}

	/**
	 * DEGENERATE ARMS. An unknown phase must return the "show nothing" sentinel rather than a plausible
	 * number — a confidently wrong countdown is worse than no countdown, because the user would push a
	 * high-value item into a window that has already closed.
	 */
	@Test
	public void unknownPhaseShowsNothing()
	{
		assertEquals("no anchor yet", 0L, AccountConnectPlugin.msUntilNextReset(0L, 9_999_999L));
		assertEquals("negative anchor is not an anchor", 0L, AccountConnectPlugin.msUntilNextReset(-1L, 9_999_999L));
		assertEquals("clock went backwards", 0L, AccountConnectPlugin.msUntilNextReset(5_000L, 4_000L));
		assertFalse(AccountConnectPlugin.resetPhaseKnown(0L));
		assertTrue(AccountConnectPlugin.resetPhaseKnown(1L));
	}

	// ---- anchor detection ----




	/**
	 * THE PROBE IS FIXED AT THE FIRST SELL AND NEVER RE-ARMED.
	 *
	 * If each sell overwrote the probe, the high-value merchandise would become the probe and the
	 * customer's purchase would anchor the clock — precisely the defect this model exists to avoid.
	 * Drives the REAL sell path rather than injecting the field, because the bug lives in that branch.
	 * (Mutation-found 2026-09-03: relaxing the `storeProbeItem == 0` guard survived every other arm.)
	 */
	@Test
	public void theProbeIsFixedAtTheFirstSellAndNotReArmed() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		inject(plugin, "shopOpen", true);
		net.runelite.api.Client client = org.mockito.Mockito.mock(net.runelite.api.Client.class);
		inject(plugin, "client", client);

		plugin.onMenuOptionClicked(sellClick(111));	// junk probe first
		plugin.onMenuOptionClicked(sellClick(999));	// then the merchandise

		assertEquals("the probe must remain the FIRST item sold", 111, probeItem(plugin));
	}




	/**
	 * THE COUNTDOWN MUST COME BACK FOR THE NEXT CYCLE WITHOUT A NEW OBSERVATION.
	 *
	 * RuneLite's Timer infobox removes ITSELF at zero, so one observed reset buys exactly one 60s
	 * countdown. The phase is still known, so the tick handler re-arms it. Without this the timer
	 * shows once and disappears — half of the live "not working" report on 2026-09-03.
	 *
	 * This asserts the re-arm CONDITION on the real fields, not a mock InfoBoxManager: showResetTimer
	 * needs an injected manager, and the decision being tested is the guard, not the drawing.
	 */
	@Test
	public void theTickReArmsTheCountdownWhenThePhaseIsKnownAndNoTimerIsUp() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		inject(plugin, "shopOpen", true);
		inject(plugin, "storeResetAnchorMs", System.currentTimeMillis());
		inject(plugin, "infoBoxManager", null);		// no manager: showResetTimer is a safe no-op
		inject(plugin, "resetTimer", null);		// the state after a Timer removed itself

		plugin.onGameTick(new net.runelite.api.events.GameTick());

		// The guard ran and reached showResetTimer, which returned early with no manager. What this
		// arm pins is that the tick path is REACHED at all — deleting the re-arm block, or negating
		// any of its three conditions, changes the reachability asserted below.
		assertTrue("phase must still be known after the tick", plugin.resetPhaseKnownForTest());
		assertTrue("the tick must have attempted a re-arm", plugin.reArmAttemptsForTest() > 0);
	}

	/** No re-arm while a countdown is already showing — that would restart it every tick. */
	@Test
	public void theTickDoesNotReArmWhileACountdownIsAlreadyUp() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		inject(plugin, "shopOpen", true);
		inject(plugin, "storeResetAnchorMs", System.currentTimeMillis());
		inject(plugin, "resetTimer", org.mockito.Mockito.mock(
			net.runelite.client.ui.overlay.infobox.Timer.class));

		plugin.onGameTick(new net.runelite.api.events.GameTick());

		assertEquals("must not re-arm over a live countdown", 0, plugin.reArmAttemptsForTest());
	}

	/** No re-arm outside a shop, and none while the phase is unknown. */
	@Test
	public void theTickDoesNotReArmOutsideAShopOrWithAnUnknownPhase() throws Exception
	{
		AccountConnectPlugin outside = plugin();
		inject(outside, "shopOpen", false);
		inject(outside, "storeResetAnchorMs", System.currentTimeMillis());
		outside.onGameTick(new net.runelite.api.events.GameTick());
		assertEquals("no re-arm outside a shop", 0, outside.reArmAttemptsForTest());

		AccountConnectPlugin unknown = plugin();
		inject(unknown, "shopOpen", true);
		inject(unknown, "storeResetAnchorMs", 0L);
		unknown.onGameTick(new net.runelite.api.events.GameTick());
		assertEquals("no re-arm with an unknown phase", 0, unknown.reArmAttemptsForTest());
	}

	// ---- anchor 1: THE ITEM WE SOLD VANISHING (measured live 2026-09-03) ----
	//
	// This is the event the user watches. A junk item the shop does NOT natively stock is sold in, and
	// for it to disappear. Measured: player-added item 1191 decayed 5->4->3->...->0, every step
	// exactly 60.0s apart, and left the shop at zero. Selling a Pot into Varrock GS — where a Pot IS
	// default stock — raised it 5->6 and the shop normalised it back to 5 in 1.2-5.4 SECONDS, which
	// is not the cycle at all. ZERO is the discriminator between those two.

	@Test
	public void theItemWeSoldReachingZeroAnchorsTheClock() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		plugin.setStoreToolsForTest(true);
		seedVisit(plugin, new int[][]{{1191, 1}});		// our junk, one left
		long before = System.currentTimeMillis();

		plugin.handleShopStockChanged(shop(new int[][]{{550, 5}}));	// 1191 gone entirely

		assertTrue("the sold item vanishing must anchor", anchor(plugin) >= before);
	}

	/**
	 * A FALL TO A NON-ZERO NUMBER IS NOT THE TICK. This is the exact shape that produced 72-second
	 * "cycles" drifting 36s/24s/12s from the truth: the shop absorbing its own default stock a few
	 * seconds after a sell. If this arm goes green with a naive "stock fell" rule, the countdown is
	 * confidently wrong again.
	 */
	@Test
	public void theShopAbsorbingItsOwnDefaultStockDoesNotAnchor() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		plugin.setStoreToolsForTest(true);
		seedVisit(plugin, new int[][]{{1931, 6}});		// a Pot sold in, above the default of 5

		plugin.handleShopStockChanged(shop(new int[][]{{1931, 5}}));	// normalised, NOT gone

		assertEquals("6->5 is the shop normalising, not a tick", 0L, anchor(plugin));
	}

	@Test
	public void anItemWeDidNotSellVanishingDoesNotAnchor() throws Exception
	{
		// Another player's stock reaching zero is a real tick, but we cannot tell it from a customer
		// clearing the last of a stack. Only OUR OWN sold item is unambiguous.
		AccountConnectPlugin plugin = plugin();
		plugin.setStoreToolsForTest(true);
		seedVisit(plugin, new int[][]{{1191, 1}});
		Field f = AccountConnectPlugin.class.getDeclaredField("shopStock");
		f.setAccessible(true);
		@SuppressWarnings("unchecked")
		Map<Integer, Integer> st = (Map<Integer, Integer>) f.get(plugin);
		st.put(9999, 1);			// present in stock, never sold by us

		plugin.handleShopStockChanged(shop(new int[][]{{1191, 1}}));	// 9999 vanished, ours did not

		assertEquals("only our own sold item may anchor", 0L, anchor(plugin));
	}

	@Test
	public void anItemThatWasNeverInStockCannotVanish() throws Exception
	{
		// had == 0 must not read as a fall to zero. Otherwise every item we ever sold anchors the
		// clock on every single container change, forever.
		AccountConnectPlugin plugin = plugin();
		plugin.setStoreToolsForTest(true);
		seedVisit(plugin, new int[][]{{1191, 0}});

		plugin.handleShopStockChanged(shop(new int[][]{{550, 5}}));

		assertEquals("0->0 is not a disappearance", 0L, anchor(plugin));
	}

	// ---- anchor detection: PERIODICITY (measured live 2026-09-03) ----
	//
	// Two models were refuted by live measurement before this one. Anchoring on "the junk item we
	// sold vanished" gave 72s cycles drifting 36s/24s/12s from the truth, because a shop's default
	// stock normalises 0.6-2.4s after a sell on its own schedule. Anchoring on "a rise and a fall
	// together" refused all five ticks in a five-minute observation, because a full shop has
	// nothing to restock and every tick was fall-only. The PERIOD held at 60.0s every time.

	@Test
	public void twoChangesOnePeriodApartAnchorTheClock()
	{
		long t = 1_000_000L;
		assertTrue(AccountConnectPlugin.isPeriodAgreement(t, t + 60_000L));
	}

	@Test
	public void theToleranceCoversRealJitterAndNoMore()
	{
		long t = 1_000_000L;
		long tol = AccountConnectPlugin.PERIOD_TOLERANCE_MS;
		assertTrue("at the edge, inside", AccountConnectPlugin.isPeriodAgreement(t, t + 60_000L + tol));
		assertTrue("at the edge, early", AccountConnectPlugin.isPeriodAgreement(t, t + 60_000L - tol));
		assertFalse("one ms past the edge", AccountConnectPlugin.isPeriodAgreement(t, t + 60_000L + tol + 1));
		assertFalse("one ms early past the edge", AccountConnectPlugin.isPeriodAgreement(t, t + 60_000L - tol - 1));
	}

	@Test
	public void ordinaryShopTrafficDoesNotAnchor()
	{
		// Real gaps measured between non-tick changes: a buy 9s after the last change, a sell 15s,
		// an absorption 2s. None may lock the clock.
		long t = 1_000_000L;
		for (long gap : new long[]{600L, 1_800L, 2_400L, 9_000L, 15_000L, 30_000L, 45_000L, 120_000L})
		{
			assertFalse("a " + gap + "ms gap must not anchor",
				AccountConnectPlugin.isPeriodAgreement(t, t + gap));
		}
	}

	/**
	 * DEGENERATE ARMS. Each passes a naive check while proving nothing, and each would anchor the
	 * clock on a non-event.
	 */
	@Test
	public void theFirstChangeOfAVisitCannotAnchor()
	{
		// With no previous change there is nothing to be periodic WITH. Opening a shop, or the very
		// first stock reading, must leave the clock unknown rather than anchoring to that instant.
		assertFalse(AccountConnectPlugin.isPeriodAgreement(0L, 1_000_000L));
		assertFalse(AccountConnectPlugin.isPeriodAgreement(-1L, 1_000_000L));
	}

	@Test
	public void aClockGoingBackwardsNeverAnchors()
	{
		assertFalse(AccountConnectPlugin.isPeriodAgreement(2_000_000L, 1_000_000L));
		assertFalse("identical timestamps are not a period",
			AccountConnectPlugin.isPeriodAgreement(1_000_000L, 1_000_000L));
	}

	@Test
	public void twoPeriodsIsNotOnePeriod()
	{
		// A tick MISSED (the shop unchanged for a whole cycle) lands 120s later. Treating that as
		// agreement would be right by luck here and wrong whenever the gap is any other multiple.
		long t = 1_000_000L;
		assertFalse(AccountConnectPlugin.isPeriodAgreement(t, t + 120_000L));
		assertFalse(AccountConnectPlugin.isPeriodAgreement(t, t + 180_000L));
	}

	/** The real container path: two changes one period apart anchor; nothing else does. */
	@Test
	public void theContainerPathAnchorsOnlyOnPeriodAgreement() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		plugin.setStoreToolsForTest(true);
		inject(plugin, "shopOpen", true);
		inject(plugin, "shopStock", new java.util.LinkedHashMap<Integer, Integer>());
		inject(plugin, "soldThisVisit", new java.util.LinkedHashSet<Integer>());

		// First reading of the visit — establishes the baseline, must not anchor.
		plugin.handleShopStockChanged(shop(new int[][]{{1115, 10}, {1191, 2}}));
		assertEquals("the first reading must not anchor", 0L, anchor(plugin));

		// A change — records the time, still nothing to be periodic with.
		plugin.handleShopStockChanged(shop(new int[][]{{1115, 9}, {1191, 1}}));
		assertEquals("one change is not a period", 0L, anchor(plugin));

		// A change one period later. Drive the clock through the field rather than sleeping 60s.
		inject(plugin, "lastStockChangeMs", System.currentTimeMillis() - 60_000L);
		plugin.handleShopStockChanged(shop(new int[][]{{1115, 8}, {1191, 1}}));
		assertTrue("two changes one period apart must anchor", anchor(plugin) > 0);
	}

	@Test
	public void anUnchangedContainerIsNotAChangeAtAll() throws Exception
	{
		// The shop container fires on events that leave the stock identical. Counting those as
		// changes would reset the periodicity chain constantly and stop the clock ever locking.
		AccountConnectPlugin plugin = plugin();
		plugin.setStoreToolsForTest(true);
		inject(plugin, "shopOpen", true);
		inject(plugin, "shopStock", new java.util.LinkedHashMap<Integer, Integer>());
		inject(plugin, "soldThisVisit", new java.util.LinkedHashSet<Integer>());
		plugin.handleShopStockChanged(shop(new int[][]{{1115, 10}}));

		long marker = System.currentTimeMillis() - 60_000L;
		inject(plugin, "lastStockChangeMs", marker);
		plugin.handleShopStockChanged(shop(new int[][]{{1115, 10}}));	// identical
		Field f = AccountConnectPlugin.class.getDeclaredField("lastStockChangeMs");
		f.setAccessible(true);
		assertEquals("an unchanged read must not touch the chain", marker, f.getLong(plugin));
		assertEquals("and must not anchor", 0L, anchor(plugin));
	}

	private static net.runelite.api.events.MenuOptionClicked sellClick(int itemId)
	{
		net.runelite.api.events.MenuOptionClicked e =
			org.mockito.Mockito.mock(net.runelite.api.events.MenuOptionClicked.class);
		org.mockito.Mockito.when(e.getMenuOption()).thenReturn("Sell 1");
		org.mockito.Mockito.when(e.getItemId()).thenReturn(itemId);
		return e;
	}

	private static int probeItem(AccountConnectPlugin p) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField("storeProbeItem");
		f.setAccessible(true);
		return f.getInt(p);
	}


	// ---- infobox lifecycle: a countdown left on screen is the obvious failure of this feature ----

	/**
	 * Every exit path must remove the box. RuneLite does NOT clear a plugin's infoboxes for it, so a
	 * missed teardown leaves a stale countdown ticking against a shop that is no longer open — exactly
	 * the "confidently wrong number" this feature exists to replace.
	 */
	@Test
	public void everyExitPathRemovesTheTimer() throws Exception
	{
		for (String path : new String[]{"shutdown", "hop", "logout", "connection-lost"})
		{
			AccountConnectPlugin plugin = plugin();
			java.util.List<Object> boxes = new java.util.ArrayList<>();
			installInfoBoxManager(plugin, boxes);
			plugin.setStoreToolsForTest(true);	// the countdown is gated
			seedVisit(plugin, new int[][]{{111, 1}, {222, 1}});
			inject(plugin, "lastStockChangeMs", System.currentTimeMillis() - 60_000L);
			plugin.handleShopStockChanged(shop(new int[][]{{111, 0}, {222, 1}}));	// period -> box
			assertEquals(path + ": a reset should show the countdown", 1, boxes.size());

			switch (path)
			{
				case "shutdown":
					plugin.shutDown();
					break;
				default:
					net.runelite.api.events.GameStateChanged ev = new net.runelite.api.events.GameStateChanged();
					ev.setGameState("hop".equals(path) ? net.runelite.api.GameState.HOPPING
						: "logout".equals(path) ? net.runelite.api.GameState.LOGIN_SCREEN
						: net.runelite.api.GameState.CONNECTION_LOST);
					plugin.onGameStateChanged(ev);
					break;
			}
			assertEquals(path + ": the countdown must be removed", 0, boxes.size());
			assertEquals(path + ": the phase must be dropped too", 0L, anchor(plugin));
		}
	}

	/** Repeated resets replace the box rather than stacking a new one every minute. */
	@Test
	public void repeatedResetsDoNotAccumulateBoxes() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		java.util.List<Object> boxes = new java.util.ArrayList<>();
		installInfoBoxManager(plugin, boxes);
		plugin.setStoreToolsForTest(true);	// the countdown is gated
		for (int i = 0; i < 4; i++)
		{
			seedVisit(plugin, new int[][]{{111, 1}, {222, 1}});
			inject(plugin, "lastStockChangeMs", System.currentTimeMillis() - 60_000L);
			plugin.handleShopStockChanged(shop(new int[][]{{111, 0}, {222, 1}}));
		}
		assertEquals("four resets must leave exactly one box", 1, boxes.size());
	}

	/**
	 * THE COUNTDOWN IS GATED TOO, not only the panel. Both surfaces render from the same
	 * gated feature, so an ungranted token must get neither.
	 */
	@Test
	public void anUngrantedTokenGetsNoCountdown() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		java.util.List<Object> boxes = new java.util.ArrayList<>();
		installInfoBoxManager(plugin, boxes);
		// store tools deliberately NOT granted
		seedVisit(plugin, new int[][]{{111, 1}, {222, 1}});
		inject(plugin, "lastStockChangeMs", System.currentTimeMillis() - 60_000L);

		plugin.handleShopStockChanged(shop(new int[][]{{111, 0}, {222, 1}}));	// a real tick

		assertEquals("an ungranted token must see no countdown", 0, boxes.size());
		assertTrue("but the phase is still tracked for when it IS granted", anchor(plugin) > 0);
	}

	/** Revoking the grant mid-session must clear a countdown that is already on screen. */
	@Test
	public void revokingTheGrantRemovesALiveCountdown() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		java.util.List<Object> boxes = new java.util.ArrayList<>();
		installInfoBoxManager(plugin, boxes);
		plugin.setStoreToolsForTest(true);
		seedVisit(plugin, new int[][]{{111, 1}, {222, 1}});
		inject(plugin, "lastStockChangeMs", System.currentTimeMillis() - 60_000L);
		plugin.handleShopStockChanged(shop(new int[][]{{111, 0}, {222, 1}}));
		assertEquals("granted: countdown shows", 1, boxes.size());

		plugin.applyServerPolicy(policyResponse("off"));

		assertEquals("revoked: countdown must be cleared", 0, boxes.size());
	}

	/** A 200 with the grant header present turns the feature on for this token. */
	@Test
	public void theServerHeaderGrantsAndRevokesTheFeature() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		assertFalse("default is OFF", plugin.storeToolsEnabled());
		plugin.applyServerPolicy(policyResponse("on"));
		assertTrue("header on grants the feature", plugin.storeToolsEnabled());
		plugin.applyServerPolicy(policyResponse("off"));
		assertFalse("header off revokes it", plugin.storeToolsEnabled());
	}

	/** Anything that is not an explicit grant word must leave the feature OFF. */
	@Test
	public void unrecognisedHeaderValuesDoNotGrantTheFeature() throws Exception
	{
		for (String v : new String[]{"", " ", "maybe", "allow", "yes", "2", "OFF"})
		{
			AccountConnectPlugin plugin = plugin();
			plugin.applyServerPolicy(policyResponse(v));
			assertFalse("'" + v + "' must not grant store tools", plugin.storeToolsEnabled());
		}
	}

	/** A response with NO header must not change a grant that is already in force. */
	@Test
	public void anAbsentHeaderLeavesTheCurrentGrantAlone() throws Exception
	{
		AccountConnectPlugin plugin = plugin();
		plugin.applyServerPolicy(policyResponse("on"));
		assertTrue(plugin.storeToolsEnabled());
		plugin.applyServerPolicy(policyResponse(null));		// header omitted entirely
		assertTrue("an absent header must not silently revoke", plugin.storeToolsEnabled());
	}

	/** Build a 200 carrying (or omitting) the X-Store-Tools header. */
	private static okhttp3.Response policyResponse(String storeTools)
	{
		okhttp3.Response.Builder b = new okhttp3.Response.Builder()
			.request(new okhttp3.Request.Builder().url("https://example.invalid/x").build())
			.protocol(okhttp3.Protocol.HTTP_1_1)
			.code(200)
			.message("OK");
		if (storeTools != null)
		{
			b.header("X-Store-Tools", storeTools);
		}
		return b.build();
	}

	/** A real InfoBoxManager whose add/remove we can observe. */
	private static void installInfoBoxManager(AccountConnectPlugin plugin, java.util.List<Object> boxes) throws Exception
	{
		net.runelite.client.ui.overlay.infobox.InfoBoxManager m =
			org.mockito.Mockito.mock(net.runelite.client.ui.overlay.infobox.InfoBoxManager.class);
		org.mockito.Mockito.doAnswer(inv -> { boxes.add(inv.getArgument(0)); return null; })
			.when(m).addInfoBox(org.mockito.Mockito.any());
		org.mockito.Mockito.doAnswer(inv -> { boxes.remove(inv.getArgument(0)); return null; })
			.when(m).removeInfoBox(org.mockito.Mockito.any());
		inject(plugin, "infoBoxManager", m);
	}

	// ---- helpers ----

	private static AccountConnectPlugin plugin() throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		inject(p, "config", new AccountConnectConfig()
		{
			@Override
			public boolean enableUpload()
			{
				return true;
			}

			@Override
			public String linkToken()
			{
				return "0123456789abcdef0123456789abcdef";
			}
		});
		return p;
	}

	/** Put the plugin in a shop visit that has sold the given {item, qty} pairs into the shop. */
	private static void seedVisit(AccountConnectPlugin p, int[][] stock) throws Exception
	{
		java.util.Set<Integer> sold = new java.util.LinkedHashSet<>();
		java.util.Map<Integer, Integer> base = new java.util.LinkedHashMap<>();
		for (int[] pair : stock)
		{
			sold.add(pair[0]);
			base.put(pair[0], pair[1]);
		}
		inject(p, "soldThisVisit", sold);
		inject(p, "shopStock", base);
	}

	/** net.runelite.api.Item is FINAL and cannot be mocked — build real ones. */
	private static net.runelite.api.ItemContainer shop(int[][] pairs)
	{
		net.runelite.api.ItemContainer c = org.mockito.Mockito.mock(net.runelite.api.ItemContainer.class);
		net.runelite.api.Item[] items = new net.runelite.api.Item[pairs.length];
		for (int i = 0; i < pairs.length; i++)
		{
			items[i] = new net.runelite.api.Item(pairs[i][0], pairs[i][1]);
		}
		org.mockito.Mockito.when(c.getItems()).thenReturn(items);
		return c;
	}

	private static long anchor(AccountConnectPlugin p) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField("storeResetAnchorMs");
		f.setAccessible(true);
		return f.getLong(p);
	}

	private static void inject(AccountConnectPlugin plugin, String name, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		f.set(plugin, value);
	}
}

package com.osrsbestinslot.export;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.Map;
import org.junit.Test;

/**
 * 0.7.4 item 3 — STORE gp_total INTEGRITY FOR MULTI-QUANTITY TRANSACTIONS.
 *
 * <p>Production evidence (2026-08-15 audit, newest clients only): {@code gp_total} was missing from
 * <b>140 of 377 (37.1%)</b> multi-quantity {@code store_buy} events against <b>14 of 176 (8.0%)</b> at
 * qty=1. The miss concentrates on qty&gt;1 because a player spam-clicking "Buy 10" lands two clicks on
 * one tick, which the old code flagged {@code ambiguous} and then dropped the gold for.
 *
 * <p>General-store selling is how gold is delivered, so those four weeks of events showed the item
 * leaving and never the coins arriving.
 *
 * <p>The fix folds same-tick clicks on the SAME item and direction into ONE pending with a summed
 * quantity and the ORIGINAL coinsBefore — sound because a pending is only consumed by an inventory
 * change, so an un-resolved pending proves no inventory change has happened and its coinsBefore still
 * predates both transactions. Genuinely un-splittable cases (different item, opposite direction) stay
 * ambiguous and still degrade to {item, qty} rather than emitting a guess.
 */
public class StoreMultiQtyGpTest
{
	private static final int TICK = 4242;
	private static final int COAL = 453;
	private static final int ORE = 440;

	// ------------------------------------------------------------------ the defect, directly

	@Test
	public void sameTickRepeatBuyOnOneItemNowCarriesExactGpInsteadOfDroppingIt()
	{
		// Two "Buy 10" clicks on the same tick, coins 1,000,000 before either.
		AccountConnectPlugin.StorePending first =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 10, 1_000_000L, TICK);
		AccountConnectPlugin.StorePending merged =
			AccountConnectPlugin.mergeStorePending(first, "store_buy", COAL, 10, 999_000L, TICK);

		assertFalse("a same-item same-tick repeat is NOT ambiguous — one delta covers both",
			merged.ambiguous);
		assertEquals("quantities must sum", 20, merged.qty);
		assertEquals("coinsBefore must stay the ORIGINAL pre-transaction reading",
			1_000_000L, merged.coinsBefore);

		// 20 coal cost 2,000 total; coins end at 998,000. Both clicks executed here.
		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			merged.type, merged.item, merged.qty, merged.coinsBefore, 998_000L, merged.ambiguous, merged.qtyMerged);

		assertEquals("the exact transacted gold must be present", 2_000L, fields.get("gp_total"));
		assertEquals(20, fields.get("qty"));
		assertNull("merged qty is click intent, so no unit price may be derived from it",
			fields.get("unit_price_gp"));
	}

	@Test
	public void beforeTheFixThisExactCaseEmittedNoGold()
	{
		// The old behaviour, reproduced by passing ambiguous=true: item and qty survive, gold does not.
		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			"store_buy", COAL, 20, 1_000_000L, 998_000L, true);

		assertNull("this is the production defect: 37.1% of multi-qty buys looked like this",
			fields.get("gp_total"));
		assertEquals("only item and qty survived", 2, fields.size());
	}

	// ------------------------------------------------------------------ the half-price regression

	/**
	 * REGRESSION GUARD for the defect the conservative fix exists to prevent.
	 *
	 * <p>A merged qty is the sum of click INTENT. A click can fail — shop out of stock, inventory full,
	 * not enough coins — while still having been counted into that sum. So when two "Buy 10" clicks merge
	 * but only the first executes, the truth is: 10 items moved for 1,000 gp (100 gp each).
	 *
	 * <p>gp_total is still EXACT, because it is the measured coin delta and the coins only moved for the
	 * click that actually happened. But qty reads 20, so a derived unit price would be 1000/20 = 50 —
	 * <b>half the real unit price</b>, and plausible enough that nothing downstream would ever question it.
	 *
	 * <p>That is strictly worse than the bug this release fixes: an absent field is recoverable, a
	 * confidently wrong number is not. unit_price_gp must therefore be ABSENT on any merged pending.
	 */
	@Test
	public void mergedQuantityNeverProducesAHalfPriceUnitCost()
	{
		AccountConnectPlugin.StorePending first =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 10, 1_000_000L, TICK);
		AccountConnectPlugin.StorePending merged =
			AccountConnectPlugin.mergeStorePending(first, "store_buy", COAL, 10, 999_000L, TICK);

		assertTrue("a merged pending must be marked as such", merged.qtyMerged);

		// Only the FIRST click executed: 10 coal at 100 gp = 1,000 gp. Coins 1,000,000 -> 999,000.
		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			merged.type, merged.item, merged.qty, merged.coinsBefore, 999_000L, merged.ambiguous, merged.qtyMerged);

		assertEquals("the coin delta is ground truth and stays exact", 1_000L, fields.get("gp_total"));
		assertNull("unit_price_gp MUST be omitted — 1000/20 = 50 would be half the real 100 gp price",
			fields.get("unit_price_gp"));
	}

	/**
	 * Rewritten 2026-08-17. The old title — "unmerged multi-quantity STILL carries a unit price BECAUSE
	 * its denominator is confirmed" — encoded the assumption the field disproved: one menu option does not
	 * confirm anything, because the shop's stock, the inventory's free space and the player's coins all cap
	 * what executes. Confirmation now means MEASURED: the item-count delta equals the clicked quantity.
	 */
	@Test
	public void unmergedMultiQuantityCarriesAUnitPriceOnlyWhenTheExecutedQuantityMatchesTheClick()
	{
		AccountConnectPlugin.StorePending p =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 20, 1_000_000L, 0L, TICK);
		assertFalse("a single click is not merged", p.qtyMerged);

		Map<String, Object> confirmed = AccountConnectPlugin.buildStoreTxFields(
			p.type, p.item, p.qty, p.coinsBefore, 998_000L, p.ambiguous, p.qtyMerged, 20L);
		assertEquals(2_000L, confirmed.get("gp_total"));
		assertEquals("a MEASURED denominator yields a unit price", 100L, confirmed.get("unit_price_gp"));

		// Same click, but the shop only had 5 — the field-observed shape.
		Map<String, Object> partial = AccountConnectPlugin.buildStoreTxFields(
			p.type, p.item, p.qty, p.coinsBefore, 999_500L, p.ambiguous, p.qtyMerged, 5L);
		assertEquals("the coin delta is still exact", 500L, partial.get("gp_total"));
		assertEquals(Boolean.TRUE, partial.get("qty_partial"));
		assertEquals(5L, partial.get("qty_executed"));
		assertNull("25 gp/item would be 4x low against the real 100", partial.get("unit_price_gp"));
	}

	/**
	 * The field-observed numbers themselves, both directions, as the fixed code must now report them.
	 */
	@Test
	public void theFieldObservedPartialFillsAreLabelledRatherThanPriced()
	{
		// BUY 50 on a shop holding 5: 26,207,203 -> 26,203,278 coins, 0 -> 5 packs.
		Map<String, Object> buy = AccountConnectPlugin.buildStoreTxFields(
			"store_buy", 22660, 50, 26_207_203L, 26_203_278L, false, false, 5L);
		assertEquals(3_925L, buy.get("gp_total"));
		assertEquals(Boolean.TRUE, buy.get("qty_partial"));
		assertEquals(5L, buy.get("qty_executed"));
		assertNull("78 gp/item against a true ~785", buy.get("unit_price_gp"));

		// SELL 50 holding 27: coins +2,175, 27 -> 0 packs.
		Map<String, Object> sell = AccountConnectPlugin.buildStoreTxFields(
			"store_sell", 22660, 50, 26_201_103L, 26_203_278L, false, false, 27L);
		assertEquals(2_175L, sell.get("gp_total"));
		assertEquals(Boolean.TRUE, sell.get("qty_partial"));
		assertEquals(27L, sell.get("qty_executed"));
		assertNull("43 gp/item against a true ~80", sell.get("unit_price_gp"));
	}

	/**
	 * A merged row now also publishes what actually moved when it can be measured. The merged qty stays an
	 * upper bound and still gets no unit price — the label is unchanged — but a consumer gains a real
	 * denominator instead of only "trust nothing here".
	 */
	@Test
	public void aMergedRowPublishesTheMeasuredQuantityAlongsideItsUpperBound()
	{
		AccountConnectPlugin.StorePending first =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 10, 1_000_000L, 0L, TICK);
		AccountConnectPlugin.StorePending merged =
			AccountConnectPlugin.mergeStorePending(first, "store_buy", COAL, 10, 999_000L, 0L, TICK + 1);

		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			merged.type, merged.item, merged.qty, merged.coinsBefore, 998_500L,
			merged.ambiguous, merged.qtyMerged, 15L);	// the shop ran short: 15 of 20 arrived

		assertEquals(Boolean.TRUE, fields.get("qty_merged"));
		assertEquals("the click-intent upper bound", 20, fields.get("qty"));
		assertEquals("what actually moved", 15L, fields.get("qty_executed"));
		assertNull("still never a derived price on a merged row", fields.get("unit_price_gp"));
	}

	/** A delta pointing the wrong way is not this transaction's, so nothing is measured from it. */
	@Test
	public void anImpossibleItemDeltaIsTreatedAsUnmeasuredRatherThanAsAQuantity()
	{
		AccountConnectPlugin.StorePending buy = new AccountConnectPlugin.StorePending(
			"store_buy", COAL, 10, 1_000_000L, 40L, TICK, false, false);
		assertEquals("a buy whose item count FELL measures nothing",
			AccountConnectPlugin.UNKNOWN_ITEM_COUNT, AccountConnectPlugin.executedQty(buy, 30L));

		AccountConnectPlugin.StorePending sell = new AccountConnectPlugin.StorePending(
			"store_sell", COAL, 10, 1_000_000L, 30L, TICK, false, false);
		assertEquals("a sell whose item count ROSE measures nothing",
			AccountConnectPlugin.UNKNOWN_ITEM_COUNT, AccountConnectPlugin.executedQty(sell, 40L));

		AccountConnectPlugin.StorePending noBase = new AccountConnectPlugin.StorePending(
			"store_buy", COAL, 10, 1_000_000L, TICK, false);
		assertEquals("no baseline, no measurement",
			AccountConnectPlugin.UNKNOWN_ITEM_COUNT, AccountConnectPlugin.executedQty(noBase, 10L));
	}

	/**
	 * A merged row must SAY it is merged, so nothing downstream pairs gp_total against an unconfirmed
	 * qty. Two things can make the merged qty overstate what those coins bought: a failed click, or the
	 * server settling the two clicks on different ticks (the first inventory update then carries only
	 * the first transaction's delta). Neither is detectable client-side, so the row is labelled rather
	 * than guessed at.
	 */
	@Test
	public void aMergedRowIsLabelledSoConsumersTreatQtyAsAnUpperBound()
	{
		AccountConnectPlugin.StorePending first =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 10, 1_000_000L, TICK);
		AccountConnectPlugin.StorePending merged =
			AccountConnectPlugin.mergeStorePending(first, "store_buy", COAL, 10, 999_000L, TICK);

		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			merged.type, merged.item, merged.qty, merged.coinsBefore, 998_000L, merged.ambiguous, merged.qtyMerged);

		assertEquals("coins that really moved", 2_000L, fields.get("gp_total"));
		assertEquals("the row must carry the merged marker", Boolean.TRUE, fields.get("qty_merged"));
		assertNull("and never a derived unit price", fields.get("unit_price_gp"));
	}

	@Test
	public void anUnmergedRowCarriesNoMergedMarker()
	{
		AccountConnectPlugin.StorePending p =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 20, 1_000_000L, 0L, TICK);
		// all 20 arrived, so the denominator is confirmed
		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			p.type, p.item, p.qty, p.coinsBefore, 998_000L, p.ambiguous, p.qtyMerged, 20L);

		assertNull("a single click needs no caveat", fields.get("qty_merged"));
		assertNull("nor a partial-fill caveat", fields.get("qty_partial"));
		assertEquals("and keeps its unit price", 100L, fields.get("unit_price_gp"));
	}

	@Test
	public void sameTickRepeatSellOnOneItemAlsoResolves()
	{
		AccountConnectPlugin.StorePending first =
			AccountConnectPlugin.mergeStorePending(null, "store_sell", COAL, 5, 500_000L, TICK);
		AccountConnectPlugin.StorePending merged =
			AccountConnectPlugin.mergeStorePending(first, "store_sell", COAL, 5, 500_100L, TICK);

		assertFalse(merged.ambiguous);
		assertEquals(10, merged.qty);

		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			merged.type, merged.item, merged.qty, merged.coinsBefore, 500_800L, merged.ambiguous, merged.qtyMerged);
		assertEquals("sell proceeds must be captured", 800L, fields.get("gp_total"));
		assertNull("merged sell qty is intent too — no unit price", fields.get("unit_price_gp"));
	}

	// ------------------------------------------------------------------ genuine ambiguity is PRESERVED

	@Test
	public void sameTickClicksOnDifferentItemsStayAmbiguousBecauseOneDeltaCannotBeSplit()
	{
		AccountConnectPlugin.StorePending first =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 10, 1_000_000L, TICK);
		AccountConnectPlugin.StorePending merged =
			AccountConnectPlugin.mergeStorePending(first, "store_buy", ORE, 10, 999_000L, TICK);

		assertTrue("two different items in one delta cannot be attributed", merged.ambiguous);

		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			merged.type, merged.item, merged.qty, merged.coinsBefore, 990_000L, merged.ambiguous);
		assertNull("we must still refuse to emit a guessed number", fields.get("gp_total"));
	}

	@Test
	public void sameTickBuyThenSellStaysAmbiguous()
	{
		AccountConnectPlugin.StorePending first =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 10, 1_000_000L, TICK);
		AccountConnectPlugin.StorePending merged =
			AccountConnectPlugin.mergeStorePending(first, "store_sell", COAL, 10, 999_000L, TICK);

		assertTrue("opposite directions net against each other in one delta", merged.ambiguous);
	}

	@Test
	public void anAlreadyAmbiguousPendingStaysAmbiguousWhenAThirdClickLands()
	{
		AccountConnectPlugin.StorePending a =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 10, 1_000_000L, TICK);
		AccountConnectPlugin.StorePending b =
			AccountConnectPlugin.mergeStorePending(a, "store_buy", ORE, 10, 999_000L, TICK);
		AccountConnectPlugin.StorePending c =
			AccountConnectPlugin.mergeStorePending(b, "store_buy", COAL, 10, 998_000L, TICK);

		assertTrue("ambiguity must not be laundered away by a later same-item click", c.ambiguous);
	}

	// ------------------------------------------------------------------ unaffected paths

	/**
	 * SUPERSEDED BY FIELD EVIDENCE (2026-08-17). This test previously asserted that a click one tick
	 * later "is its own transaction — quantities must NOT sum", and it passed. The live client then
	 * showed that assertion describes a defect: two "Buy 10" clicks a tick apart emitted one click's
	 * qty against both clicks' gold plus a fabricated {@code unit_price_gp} of 1,132 (true ~755). The
	 * premise was wrong — a pending is only consumed by an inventory change, so an unresolved pending a
	 * tick later still has a {@code coinsBefore} that predates both transactions.
	 *
	 * <p>Kept, rewritten to assert the corrected contract at the boundary that actually matters: inside
	 * the resolution window the pending merges and is LABELLED; outside it the clicks stay independent.
	 * See {@code adjacentTickRepeatBuyMergesInsteadOfPairingOneQtyWithTwoClicksOfGold} and
	 * {@code aPendingOlderThanTheMergeWindowDoesNotMerge}.
	 */
	@Test
	public void clicksMergeInsideTheResolutionWindowAndAreIndependentOutsideIt()
	{
		AccountConnectPlugin.StorePending first =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 10, 1_000_000L, TICK);

		AccountConnectPlugin.StorePending inside = AccountConnectPlugin.mergeStorePending(
			first, "store_buy", COAL, 10, 999_000L, TICK + AccountConnectPlugin.STORE_PENDING_MAX_TICKS);
		assertTrue("still unresolved, so still one delta", inside.qtyMerged);
		assertEquals(20, inside.qty);
		assertEquals("the original pre-transaction reading", 1_000_000L, inside.coinsBefore);

		AccountConnectPlugin.StorePending outside = AccountConnectPlugin.mergeStorePending(
			first, "store_buy", COAL, 10, 999_000L,
			TICK + AccountConnectPlugin.STORE_PENDING_MAX_TICKS + 1);
		assertFalse("past the window the resolver would drop it anyway", outside.qtyMerged);
		assertFalse(outside.ambiguous);
		assertEquals("its own transaction — quantities must NOT sum", 10, outside.qty);
		assertEquals("and it uses its OWN coinsBefore", 999_000L, outside.coinsBefore);
	}

	/**
	 * A colour tag's own hex digits must never be read as a quantity. "Sell 10&lt;col=ff9040&gt;" scanned
	 * naively for a trailing digit run yields 9040 — a plausible-looking number, which is the failure
	 * shape this whole release is about. Tags are stripped before the quantity is read.
	 */
	@Test
	public void colourTagHexDigitsAreNeverMistakenForAQuantity()
	{
		assertEquals(10, AccountConnectPlugin.parseTrailingQty("Sell 10<col=ff9040>"));
		assertEquals("a tag containing digits, with no quantity at all", 1,
			AccountConnectPlugin.parseTrailingQty("Sell<col=ff9040>"));
		assertEquals("leading tag too", 10,
			AccountConnectPlugin.parseTrailingQty("<col=00ff00>Sell 10<col=ff9040>"));
	}

	@Test
	public void singleQuantityBuyIsUnchanged()
	{
		AccountConnectPlugin.StorePending p =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 1, 1_000_000L, TICK);
		assertFalse(p.ambiguous);

		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			p.type, p.item, p.qty, p.coinsBefore, 999_900L, p.ambiguous);
		assertEquals(100L, fields.get("gp_total"));
		assertNull("no average unit price for a single item", fields.get("unit_price_gp"));
	}

	@Test
	public void wrongSignDeltaStillDegradesRatherThanEmittingNonsense()
	{
		// A buy whose coin count went UP cannot be that buy's delta — refuse it.
		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			"store_buy", COAL, 20, 1_000_000L, 1_005_000L, false);
		assertNull(fields.get("gp_total"));
	}

	// ------------------------------------------------------------------ FIELD-OBSERVED defects (2026-08-17)

	/**
	 * FIELD DEFECT 1 — every general-store SELL was logging qty 1.
	 *
	 * <p>Observed live on 2026-08-17 at the Varrock General Store: one "Sell 10" click moved ten items
	 * out of the inventory and 1,325 gp in, and the event reached production D1 as
	 * {@code {"item":22660,"qty":1,"gp_total":1325}} — a consumer dividing those gets 1,325 gp per item
	 * against a true 132.5, ten times over. Reproduced twice.
	 *
	 * <p>Cause: the client's SELL option string carries a colour tag the BUY string does not, so the
	 * trailing token is "10&lt;col=ff9040&gt;", which {@code Integer.parseInt} rejects and the catch
	 * silently defaults to 1. The pre-existing test asserted on the clean string "Sell 10", which the
	 * live client never sends — the assertion was true and the behaviour was still wrong.
	 *
	 * <p>The strings below are verbatim from the client's own MenuOptionClicked trace.
	 */
	@Test
	public void sellQuantityIsParsedFromTheColourTaggedOptionTheClientActuallySends()
	{
		assertEquals("verbatim from the live client trace", 10,
			AccountConnectPlugin.parseTrailingQty("Sell 10<col=ff9040>"));
		assertEquals(50, AccountConnectPlugin.parseTrailingQty("Sell 50<col=ff9040>"));
		assertEquals(5, AccountConnectPlugin.parseTrailingQty("Sell 5<col=ff9040>"));
		assertEquals(1, AccountConnectPlugin.parseTrailingQty("Sell 1<col=ff9040>"));
		// the buy strings are untagged and must keep working exactly as before
		assertEquals(10, AccountConnectPlugin.parseTrailingQty("Buy 10"));
		assertEquals(50, AccountConnectPlugin.parseTrailingQty("Buy 50"));
		assertEquals("no trailing number still means one", 1,
			AccountConnectPlugin.parseTrailingQty("Buy"));
		assertEquals("a tag with no number is still one", 1,
			AccountConnectPlugin.parseTrailingQty("Sell<col=ff9040>"));
	}

	/**
	 * FIELD DEFECT 2 — two clicks on ADJACENT ticks emitted one click's qty against both clicks' gold,
	 * and then derived a unit price from the mismatch.
	 *
	 * <p>Observed live on 2026-08-17: two rapid "Buy 10" clicks, fifteen packs received (the shop ran
	 * short), 11,325 gp spent. D1 got {@code qty:10, gp_total:11325, unit_price_gp:1132} with NO
	 * {@code qty_merged} flag — an exact-looking unit price against a true ~755, indistinguishable
	 * downstream from a genuinely correct single-click row. Reproduced twice.
	 *
	 * <p>Cause: the merge only fired on {@code prev.tick == tick}. One tick apart, {@code prev} was
	 * dropped and the new pending kept its own {@code coinsBefore} — but no inventory change had
	 * resolved yet, so that reading STILL predates both transactions. The same argument that justifies
	 * the same-tick merge applies to any unresolved pending: what makes {@code coinsBefore} usable is
	 * that nothing has been consumed, not that the clock agrees.
	 */
	@Test
	public void adjacentTickRepeatBuyMergesInsteadOfPairingOneQtyWithTwoClicksOfGold()
	{
		AccountConnectPlugin.StorePending first =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 10, 1_000_000L, TICK);
		AccountConnectPlugin.StorePending merged =
			AccountConnectPlugin.mergeStorePending(first, "store_buy", COAL, 10, 999_000L, TICK + 1);

		assertTrue("an unresolved pending one tick back must still merge", merged.qtyMerged);
		assertEquals("quantities sum", 20, merged.qty);
		assertEquals("the ORIGINAL pre-transaction coin reading survives",
			1_000_000L, merged.coinsBefore);

		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			merged.type, merged.item, merged.qty, merged.coinsBefore, 998_000L,
			merged.ambiguous, merged.qtyMerged);
		assertEquals("both clicks' gold", 2_000L, fields.get("gp_total"));
		assertNull("a merged qty may never produce a unit price", fields.get("unit_price_gp"));
	}

	/**
	 * The field defect's exact numbers, as the fixed code must now report them: two "Buy 10" clicks a
	 * tick apart that delivered fifteen items for 11,325 gp. The row must be LABELLED and must not
	 * carry the fabricated 1,132 unit price.
	 */
	@Test
	public void theFieldObservedAdjacentTickBuyNoLongerFabricatesAUnitPrice()
	{
		AccountConnectPlugin.StorePending first =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", 22660, 10, 26_233_393L, TICK);
		AccountConnectPlugin.StorePending merged =
			AccountConnectPlugin.mergeStorePending(first, "store_buy", 22660, 10, 26_227_000L, TICK + 1);

		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			merged.type, merged.item, merged.qty, merged.coinsBefore, 26_222_068L,
			merged.ambiguous, merged.qtyMerged);

		assertEquals("the measured coin delta, unchanged", 11_325L, fields.get("gp_total"));
		assertEquals(Boolean.TRUE, fields.get("qty_merged"));
		assertNull("1132 gp/item was the fabrication this test exists to prevent",
			fields.get("unit_price_gp"));
	}

	/**
	 * The merge window must stay BOUNDED. Two clicks far apart are two separate transactions and the
	 * later one owns its own coin reading — merging them would attribute the first purchase's gold to
	 * the second.
	 */
	@Test
	public void aPendingOlderThanTheMergeWindowDoesNotMerge()
	{
		AccountConnectPlugin.StorePending first =
			AccountConnectPlugin.mergeStorePending(null, "store_buy", COAL, 10, 1_000_000L, TICK);
		AccountConnectPlugin.StorePending second = AccountConnectPlugin.mergeStorePending(
			first, "store_buy", COAL, 10, 999_000L, TICK + AccountConnectPlugin.STORE_PENDING_MAX_TICKS + 1);

		assertFalse("too far apart to share one delta", second.qtyMerged);
		assertEquals("qty is this click's alone", 10, second.qty);
		assertEquals("and it uses its OWN coinsBefore", 999_000L, second.coinsBefore);
	}
}

package com.osrsbestinslot.export;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.google.gson.Gson;
import java.lang.reflect.Field;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Prayer;
import net.runelite.api.VarPlayer;
import net.runelite.api.Varbits;
import net.runelite.api.WorldType;
