/**
 * CONTROLLED DROP -> SELF-PICKUP. Reproduces the live 2026-09-11 grokerini test: three items dropped in
 * rapid succession, one left on the ground, two picked back up by the same account.
 */
public class SelfPickupTest
{
	private static final int CHAPS = 2495;
	private static final int DIAMOND = 1617;
	private static final int COINS = 995;
	private static final int POT = 1931;
	private static final int TILE_X = 3210;
	private static final int TILE_Y = 3420;

	@Test
	public void dropThreeThenPickTwoBackUp() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(CHAPS, 1, DIAMOND, 1, COINS, 10);

		tick(plugin, 100);
		plugin.onMenuOptionClicked(menu("Drop", "", CHAPS));
		tick(plugin, 105);
		plugin.onMenuOptionClicked(menu("Drop", "", DIAMOND));
		tick(plugin, 108);
		plugin.onMenuOptionClicked(menu("Drop", "", COINS));

		setInventory(plugin);	// inventory now empty of all three
		plugin.resolveDropPendingOnGroundSpawn(CHAPS, 0, 0L, 100);
		plugin.resolveDropPendingOnGroundSpawn(DIAMOND, 0, 0L, 105);
		plugin.resolveDropPendingOnGroundSpawn(COINS, 0, 0L, 108);

		assertEquals("all three drops must emit", 3, eventsOfType(plugin, "drop").size());

		// --- pick the diamond back up ---
		tick(plugin, 140);
		plugin.onMenuOptionClicked(menu("Take", "Uncut diamond", DIAMOND));
		setInventory(plugin, DIAMOND, 1);
		plugin.onItemContainerChanged(containerChanged(plugin));

		// --- pick the 10 coins back up ---
		tick(plugin, 150);
		plugin.onMenuOptionClicked(menu("Take", "Coins", COINS));
		setInventory(plugin, DIAMOND, 1, COINS, 10);
		plugin.onItemContainerChanged(containerChanged(plugin));

		List<Integer> picked = eventsOfType(plugin, "pickup");
		assertEquals("both self-pickups must emit exactly once: " + picked, 2, picked.size());
		assertTrue("diamond self-pickup lost", picked.contains(DIAMOND));
		assertTrue("coin self-pickup lost", picked.contains(COINS));
	}


	/** Isolates the PICKUP stage: one drop only, so the single-slot drop defect cannot confound it. */
	@Test
	public void oneDropThenPickItBackUp() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(DIAMOND, 1);
		tick(plugin, 100);
		plugin.onMenuOptionClicked(menu("Drop", "", DIAMOND));
		setInventory(plugin);
		plugin.resolveDropPendingOnGroundSpawn(DIAMOND, 0, 0L, 100);
		assertEquals("the single drop must emit", 1, eventsOfType(plugin, "drop").size());

		tick(plugin, 140);
		plugin.onMenuOptionClicked(menu("Take", "Uncut diamond", DIAMOND));
		setInventory(plugin, DIAMOND, 1);
		plugin.onItemContainerChanged(containerChanged(plugin));
		assertEquals("self-pickup after own drop must emit", 1, eventsOfType(plugin, "pickup").size());
	}

	/** Bare pickup, no preceding drop — the general mechanism the corpus already shows working. */
	@Test
	public void barePickupWithNoPrecedingDrop() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin();
		tick(plugin, 200);
		plugin.onMenuOptionClicked(menu("Take", "Uncut diamond", DIAMOND));
		setInventory(plugin, DIAMOND, 1);
		plugin.onItemContainerChanged(containerChanged(plugin));
		assertEquals("bare pickup must emit", 1, eventsOfType(plugin, "pickup").size());
	}

	/**
	 * THE REAL GROUND-TAKE SHAPE, captured from a live client on 2026-09-12.
	 *
	 * Dropping a Pot and taking it back on world 308 produced exactly this MenuOptionClicked:
	 *   option=Take target=<col=ff9040>Pot id=1931 itemId=-1 param0=49 param1=54
	 *   type=GROUND_ITEM_THIRD_OPTION
	 *
	 * This test previously asserted that NO pickup is emitted here, which encoded the defect as
	 * correct behaviour and is why a green suite missed a live failure on two real staff accounts.
	 */
	@Test
	public void aRealGroundTakeEmitsItsPickup() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin();
		tick(plugin, 200);
		plugin.onMenuOptionClicked(groundTake("Pot", POT));
		setInventory(plugin, POT, 1);
		plugin.onItemContainerChanged(containerChanged(plugin));
		assertEquals("a ground Take carries its item id in the entry identifier, not getItemId()",
			1, eventsOfType(plugin, "pickup").size());
		assertEquals(Integer.valueOf(POT), eventsOfType(plugin, "pickup").get(0));
	}

	/** An entry with NEITHER source populated must still be skipped, not guessed at. */
	@Test
	public void aTakeWithNoUsableIdAnywhereStillEmitsNothing() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin();
		tick(plugin, 200);
		plugin.onMenuOptionClicked(groundTake("Pot", -1));
		setInventory(plugin, POT, 1);
		plugin.onItemContainerChanged(containerChanged(plugin));
		assertEquals(0, eventsOfType(plugin, "pickup").size());
	}

	/** The fallback is pickup-ONLY: an inventory entry's identifier is an option index, not an item. */
	@Test
	public void theIdentifierFallbackDoesNotApplyToOtherOpcodes() throws Exception
	{
		MenuOptionClicked drop = mock(MenuOptionClicked.class);
		when(drop.getMenuOption()).thenReturn("Drop");
		when(drop.getItemId()).thenReturn(-1);
		when(drop.getId()).thenReturn(7);          // the real Drop entry's identifier: option index
		assertEquals("a Drop must never adopt the option index as an item id",
			-1, AccountConnectPlugin.offBookItemId(drop, "drop"));
	}

	/**
	 * The identifier is only an item id on a GROUND_ITEM_* opcode.
	 *
	 * Matching the option word "Take" alone would adopt the identifier of any other entry that
	 * happens to be labelled Take — a widget button, a future interface — where the identifier is
	 * an option index or a widget id, not an item. The opcode is what makes the field meaningful.
	 */
	@Test
	public void aTakeOnANonGroundOpcodeNeverAdoptsItsIdentifier()
	{
		MenuOptionClicked m = mock(MenuOptionClicked.class);
		when(m.getMenuOption()).thenReturn("Take");
		when(m.getItemId()).thenReturn(-1);
		when(m.getId()).thenReturn(9764864);	// a widget id, not an item
		when(m.getMenuAction()).thenReturn(net.runelite.api.MenuAction.CC_OP_LOW_PRIORITY);
		assertEquals("only a ground-item opcode puts an item id in the identifier",
			-1, AccountConnectPlugin.offBookItemId(m, "pickup"));
	}

	/** Every ground-item option index is a valid source, not just the third. */
	@Test
	public void everyGroundItemOpcodeCarriesItsItemIdInTheIdentifier()
	{
		for (net.runelite.api.MenuAction a : new net.runelite.api.MenuAction[]{
			net.runelite.api.MenuAction.GROUND_ITEM_FIRST_OPTION,
			net.runelite.api.MenuAction.GROUND_ITEM_SECOND_OPTION,
			net.runelite.api.MenuAction.GROUND_ITEM_THIRD_OPTION,
			net.runelite.api.MenuAction.GROUND_ITEM_FOURTH_OPTION,
			net.runelite.api.MenuAction.GROUND_ITEM_FIFTH_OPTION})
		{
			MenuOptionClicked m = mock(MenuOptionClicked.class);
			when(m.getItemId()).thenReturn(-1);
			when(m.getId()).thenReturn(POT);
			when(m.getMenuAction()).thenReturn(a);
			assertEquals(a.toString(), POT, AccountConnectPlugin.offBookItemId(m, "pickup"));
		}
	}

	/** An inventory action with a good getItemId() keeps using it, identifier ignored. */
	@Test
	public void aNormalInventoryActionStillUsesGetItemId()
	{
		MenuOptionClicked drop = mock(MenuOptionClicked.class);
		when(drop.getItemId()).thenReturn(1931);
		when(drop.getId()).thenReturn(7);
		assertEquals(1931, AccountConnectPlugin.offBookItemId(drop, "drop"));
	}


	/** EXACT live shape: three drops each confirmed by its own ground spawn, then a Take. */
	@Test
	public void liveShapeThreeConfirmedDropsThenTake() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(CHAPS, 1, DIAMOND, 1, COINS, 10);
		tick(plugin, 100);
		plugin.onMenuOptionClicked(menu("Drop", "", CHAPS));
		plugin.resolveDropPendingOnGroundSpawn(CHAPS, 0, 0L, 100);
		tick(plugin, 105);
		plugin.onMenuOptionClicked(menu("Drop", "", DIAMOND));
		plugin.resolveDropPendingOnGroundSpawn(DIAMOND, 0, 0L, 105);
		tick(plugin, 108);
		plugin.onMenuOptionClicked(menu("Drop", "", COINS));
		plugin.resolveDropPendingOnGroundSpawn(COINS, 0, 0L, 108);
		setInventory(plugin);
		assertEquals("live shape: all three drops emitted", 3, eventsOfType(plugin, "drop").size());

		tick(plugin, 140);
		plugin.onMenuOptionClicked(menu("Take", "Uncut diamond", DIAMOND));
		setInventory(plugin, DIAMOND, 1);
		plugin.onItemContainerChanged(containerChanged(plugin));
		assertEquals("the self-pickup after the live drop shape must emit",
			1, eventsOfType(plugin, "pickup").size());
	}

	/** A Drop click that never gets a ground spawn leaves a pending. Does it swallow a later Take? */
	@Test
	public void staleUnconfirmedDropDoesNotSwallowALaterPickup() throws Exception
	{
		AccountConnectPlugin plugin = newPlugin(CHAPS, 1);
		tick(plugin, 100);
		plugin.onMenuOptionClicked(menu("Drop", "", CHAPS));	// no ground spawn ever arrives

		tick(plugin, 102);					// 2 ticks later, well inside DROP_PENDING_MAX_TICKS
		plugin.onMenuOptionClicked(menu("Take", "Uncut diamond", DIAMOND));
		setInventory(plugin, CHAPS, 1, DIAMOND, 1);
		plugin.onItemContainerChanged(containerChanged(plugin));
		assertEquals("a stale drop pending must not swallow a real pickup",
			1, eventsOfType(plugin, "pickup").size());
	}

	// ---------------------------------------------------------------- harness

	private static AccountConnectPlugin newPlugin(int... idQtyPairs) throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Client client = mock(Client.class);
		Player player = mock(Player.class);
		ItemContainer inv0 = container(idQtyPairs);
		when(client.getItemContainer(InventoryID.INVENTORY)).thenReturn(inv0);
		when(client.getVarbitValue(Varbits.IN_WILDERNESS)).thenReturn(0);
		when(client.getTickCount()).thenReturn(100);
		// WorldPoint.fromScene() reads the world view's base coordinates. Base 0 makes the scene
		// coordinates in a Take menu entry equal to world coordinates, which keeps the tile
		// assertions readable. Without this the conversion returns null and every tile check
		// silently degrades to item-id-only matching — i.e. passes for the wrong reason.
		net.runelite.api.WorldView wv = mock(net.runelite.api.WorldView.class);
		when(wv.getBaseX()).thenReturn(0);
		when(wv.getBaseY()).thenReturn(0);
		when(client.getTopLevelWorldView()).thenReturn(wv);
		when(client.getLocalPlayer()).thenReturn(player);
		when(player.getWorldLocation()).thenReturn(new WorldPoint(TILE_X, TILE_Y, 0));
		inject(plugin, "client", client);
		return plugin;
	}

	private static void setInventory(AccountConnectPlugin plugin, int... idQtyPairs) throws Exception
	{
		ItemContainer next = container(idQtyPairs);
		when(client(plugin).getItemContainer(InventoryID.INVENTORY)).thenReturn(next);
	}

	/** The real client hands the changed INVENTORY container to onItemContainerChanged. */
	private static net.runelite.api.events.ItemContainerChanged containerChanged(AccountConnectPlugin plugin)
		throws Exception
	{
		ItemContainer inv = client(plugin).getItemContainer(InventoryID.INVENTORY);
		return new net.runelite.api.events.ItemContainerChanged(InventoryID.INVENTORY.getId(), inv);
	}

	private static Client client(AccountConnectPlugin plugin) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField("client");
		f.setAccessible(true);
		return (Client) f.get(plugin);
	}

	private static void tick(AccountConnectPlugin plugin, int t) throws Exception
	{
		when(client(plugin).getTickCount()).thenReturn(t);
	}

	private static List<Integer> eventsOfType(AccountConnectPlugin plugin, String type)
	{
		List<Integer> out = new ArrayList<>();
		for (Map<String, Object> e : plugin.pendingEvents)
		{
			if (type.equals(e.get("type")))
			{
				out.add((Integer) e.get("item"));
			}
		}
		return out;
	}

	/** The REAL ground-item Take entry: itemId is -1, the item id sits in the identifier. */
	private static MenuOptionClicked groundTake(String name, int itemId)
	{
		return groundTakeAt(name, itemId, TILE_X, TILE_Y);
	}

	/**
	 * The REAL ground-item Take entry, aimed at one specific tile.
	 *
	 * itemId is -1, the item id sits in the identifier, the opcode is GROUND_ITEM_THIRD_OPTION and
	 * param0/param1 carry the pile's SCENE coordinates. The test client mock reports base 0, so the
	 * scene coordinates ARE the world coordinates here.
	 */
	private static MenuOptionClicked groundTakeAt(String name, int itemId, int x, int y)
	{
		MenuOptionClicked m = mock(MenuOptionClicked.class);
		when(m.getMenuOption()).thenReturn("Take");
		when(m.getMenuTarget()).thenReturn("<col=ff9040>" + name);
		when(m.getItemId()).thenReturn(-1);
		when(m.getId()).thenReturn(itemId);
		when(m.getMenuAction()).thenReturn(net.runelite.api.MenuAction.GROUND_ITEM_THIRD_OPTION);
		when(m.getParam0()).thenReturn(x);
		when(m.getParam1()).thenReturn(y);
		return m;
	}

	private static MenuOptionClicked menu(String option, String target, int itemId)
	{
		MenuOptionClicked m = mock(MenuOptionClicked.class);
		when(m.getMenuOption()).thenReturn(option);
		when(m.getMenuTarget()).thenReturn(target);
		when(m.getItemId()).thenReturn(itemId);
		return m;
	}

	private static ItemContainer container(int... idQtyPairs)
	{
		ItemContainer c = mock(ItemContainer.class);
		Item[] items = new Item[idQtyPairs.length / 2];
		for (int i = 0; i < items.length; i++)
		{
			items[i] = new Item(idQtyPairs[i * 2], idQtyPairs[i * 2 + 1]);
		}
		when(c.getItems()).thenReturn(items);
		return c;
	}

	private static void inject(Object target, String field, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(field);
		f.setAccessible(true);
		f.set(target, value);
	}

	private static AccountConnectConfig onConfig()
	{
		return (AccountConnectConfig) java.lang.reflect.Proxy.newProxyInstance(
			AccountConnectConfig.class.getClassLoader(),
			new Class<?>[]{AccountConnectConfig.class},
			(proxy, method, args) -> {
				Class<?> rt = method.getReturnType();
				if (rt == boolean.class || rt == Boolean.class) { return Boolean.TRUE; }
				if (rt == String.class) { return "0123456789abcdef0123456789abcdef"; }
				if (rt == int.class || rt == Integer.class) { return 0; }
				return null;
			});
	}
}

package com.osrsbestinslot.export;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.lang.reflect.Field;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.StatChanged;
import org.junit.Test;

/**
 * WAVE 3 — event enrichment: logout reason (idle / manual / six_hour_cap / connection_lost), login+logout
 * wealth, level_up xp, and death location. store_* price is intentionally NOT added (no clean transacted-price
 * API off the shop widget — see the note in onMenuOptionClicked); items-lost on death is deferred likewise.
 */
public class Wave3EnrichmentTest
{
	private static final String TOKEN = "0123456789abcdef0123456789abcdef";

	private static AccountConnectConfig onConfig()
	{
		return new AccountConnectConfig()
		{
			@Override public boolean enableUpload() { return true; }

			@Override
			public String linkToken()
			{
				return TOKEN;
			}
		};
	}

	private static void inject(AccountConnectPlugin plugin, String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private static AccountConnectPlugin linkedPlugin() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		inject(plugin, "activeRsn", "TestPlayer");
		inject(plugin, "activeHash", "42");
		inject(plugin, "sessionActive", true);
		return plugin;
	}

	private static Map<String, Object> snapshotWithNetWorth(long net)
	{
		Map<String, Object> wealth = new LinkedHashMap<>();
		wealth.put("net_worth_gp", net);
		Map<String, Object> snap = new LinkedHashMap<>();
		snap.put("wealth", wealth);
		return snap;
	}

	@Test
	public void logoutReasonManualWhenNotIdle() throws Exception
	{
		AccountConnectPlugin plugin = linkedPlugin();
		inject(plugin, "sessionStartMillis", System.currentTimeMillis() - 60_000L);
		inject(plugin, "lastKeyboardIdleTicks", 3);
		inject(plugin, "lastMouseIdleTicks", 1);	// just clicked -> manual
		plugin.trackLogout();
		assertEquals("manual", plugin.pendingEvents.get(0).get("reason"));
	}

	@Test
	public void logoutReasonIdleWhenIdleTicksHigh() throws Exception
	{
		AccountConnectPlugin plugin = linkedPlugin();
		inject(plugin, "sessionStartMillis", System.currentTimeMillis() - 60_000L);
		inject(plugin, "lastKeyboardIdleTicks", 900);
		inject(plugin, "lastMouseIdleTicks", 900);	// no input for minutes -> idle
		plugin.trackLogout();
		assertEquals("idle", plugin.pendingEvents.get(0).get("reason"));
	}

	@Test
	public void logoutReasonSixHourCapWhenSessionNearSixHours() throws Exception
	{
		AccountConnectPlugin plugin = linkedPlugin();
		inject(plugin, "sessionStartMillis", System.currentTimeMillis() - (6L * 60L * 60L * 1000L));
		inject(plugin, "lastKeyboardIdleTicks", 0);
		inject(plugin, "lastMouseIdleTicks", 0);
		plugin.trackLogout();
		assertEquals("six_hour_cap", plugin.pendingEvents.get(0).get("reason"));
	}

	@Test
	public void connectionLostEmitsLogoutWithReason() throws Exception
	{
		AccountConnectPlugin plugin = linkedPlugin();
		inject(plugin, "sessionStartMillis", System.currentTimeMillis() - 60_000L);
		GameStateChanged ev = new GameStateChanged();
		ev.setGameState(GameState.CONNECTION_LOST);
		plugin.onGameStateChanged(ev);

		assertEquals(1, plugin.pendingEvents.size());
		Map<String, Object> e = plugin.pendingEvents.get(0);
		assertEquals("logout", e.get("type"));
		assertEquals("connection_lost", e.get("reason"));
		assertFalse("connection loss ends the session", getBool(plugin, "sessionActive"));
	}

	@Test
	public void logoutCarriesWealthFromLastSnapshot() throws Exception
	{
		AccountConnectPlugin plugin = linkedPlugin();
		inject(plugin, "sessionStartMillis", System.currentTimeMillis() - 60_000L);
		inject(plugin, "lastBuiltSnapshot", snapshotWithNetWorth(1_234_567L));
		plugin.trackLogout();
		assertEquals(1_234_567L, plugin.pendingEvents.get(0).get("wealth"));
	}

	@Test
	public void loginCarriesWealthFromLastSnapshot() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Client client = mock(Client.class);
		Player player = mock(Player.class);
		when(client.getLocalPlayer()).thenReturn(player);
		when(player.getName()).thenReturn("TestPlayer");
		when(client.getAccountHash()).thenReturn(42L);
		inject(plugin, "client", client);
		inject(plugin, "lastBuiltSnapshot", snapshotWithNetWorth(555L));

		boolean newLogin = plugin.trackSessionStart();
		assertTrue(newLogin);
		Map<String, Object> e = plugin.pendingEvents.get(0);
		assertEquals("login", e.get("type"));
		assertEquals(555L, e.get("wealth"));
	}

	@Test
	public void netWorthFallsBackToInventoryPlusEquipmentWhenBankNull() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		Map<String, Object> wealth = new LinkedHashMap<>();
		wealth.put("net_worth_gp", null);	// bank not opened yet
		wealth.put("inventory_gp", 300L);
		wealth.put("equipment_gp", 200L);
		Map<String, Object> snap = new LinkedHashMap<>();
		snap.put("wealth", wealth);
		inject(plugin, "lastBuiltSnapshot", snap);
		assertEquals(Long.valueOf(500L), plugin.lastKnownNetWorth());
	}

	@Test
	public void levelUpCarriesXp() throws Exception
	{
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Client client = mock(Client.class);
		when(client.getSkillExperience(Skill.ATTACK)).thenReturn(13_363);
		inject(plugin, "client", client);

		// StatChanged is a final class -> construct directly (Skill, xp, level, boostedLevel).
		plugin.onStatChanged(new StatChanged(Skill.ATTACK, 12_000, 24, 24));	// primes previous level, no emit
		plugin.onStatChanged(new StatChanged(Skill.ATTACK, 13_363, 25, 25));	// real level increase -> emit

		assertEquals(1, plugin.pendingEvents.size());
		Map<String, Object> e = plugin.pendingEvents.get(0);
		assertEquals("level_up", e.get("type"));
		assertEquals(25, e.get("level"));
		assertEquals(13_363, e.get("xp"));
	}

	@Test
	public void deathDefersThenCarriesLocationAndKind() throws Exception
	{
		// Deferred model: ActorDeath arms a pending (reads pre-death inv+equip live) and emits NOTHING; the
		// death event with location + death_kind is emitted once the containers settle (syncTask) or on logout.
		// This mock is a SAFE death (no wilderness varbit / pvp world), so it carries NO items_lost — a safe death
		// is a gp-sink reclaim, not an inter-account transfer, and its diff would be polluted by post-death eating.
		AccountConnectPlugin plugin = new AccountConnectPlugin();
		inject(plugin, "config", onConfig());
		Client client = mock(Client.class);
		Player player = mock(Player.class);
		WorldPoint wp = new WorldPoint(3200, 3200, 0);
		when(client.getLocalPlayer()).thenReturn(player);
		when(player.getWorldLocation()).thenReturn(wp);
		inject(plugin, "client", client);

		// ActorDeath is a final class -> construct directly with the (mockable) player as the dead actor.
		plugin.onActorDeath(new ActorDeath((Actor) player));
		assertTrue("death emit is deferred to the settle/logout resolve", plugin.pendingEvents.isEmpty());

		plugin.resolveDeathPending(new LinkedHashMap<>(), true); // settle-window path
		assertEquals(1, plugin.pendingEvents.size());
		Map<String, Object> e = plugin.pendingEvents.get(0);
		assertEquals("death", e.get("type"));
		assertEquals("safe", e.get("death_kind")); // no wilderness varbit / pvp world in the mock
		assertFalse("safe death carries no items_lost (not a transfer)", e.containsKey("items_lost"));
		@SuppressWarnings("unchecked")
		Map<String, Object> loc = (Map<String, Object>) e.get("location");
		assertEquals(wp.getRegionID(), loc.get("region_id"));
		assertEquals(0, loc.get("plane"));
	}

	private static boolean getBool(AccountConnectPlugin plugin, String fieldName) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		return f.getBoolean(plugin);
	}
}

package com.osrsbestinslot.export;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The standalone reset countdown. Split from the nearby panel because a list that changes height
 * moved the number around the screen — so the arms here are mostly about STAYING STILL.
 */
public class StoreResetOverlayTest
{
	private static Graphics2D graphics()
	{
		return new BufferedImage(400, 300, BufferedImage.TYPE_INT_ARGB).createGraphics();
	}

	private static AccountConnectPlugin plugin() throws Exception
	{
		AccountConnectPlugin p = new AccountConnectPlugin();
		java.lang.reflect.Field f = AccountConnectPlugin.class.getDeclaredField("config");
		f.setAccessible(true);
		f.set(p, new AccountConnectConfig()
		{
			@Override
			public boolean enableUpload()
			{
				return true;
			}

			@Override
			public String linkToken()
			{
				return "0123456789abcdef0123456789abcdef";
			}
		});
		return p;
	}

	/**
	 * THE JITTER FIX. The overlay must draw exactly one row in every state, so its height can never
	 * change. This is the whole reason it is a separate overlay.
	 */
	@Test
	public void alwaysDrawsExactlyOneRowWhateverTheState() throws Exception
	{
		AccountConnectPlugin p = plugin();
		p.setShopOpenForTest(true);
		p.setStoreToolsForTest(true);
		StoreResetOverlay o = new StoreResetOverlay(p);

		// phase unknown
		o.render(graphics());
		assertEquals("waiting state must be one row", 1, o.builtRowCountForTest());

		// phase known — drive the anchor through the real field
		java.lang.reflect.Field a = AccountConnectPlugin.class.getDeclaredField("storeResetAnchorMs");
		a.setAccessible(true);
		a.setLong(p, System.currentTimeMillis() - 30_000L);
		o.render(graphics());
		assertEquals("counting state must also be one row", 1, o.builtRowCountForTest());
	}

	@Test
	public void repeatedRendersDoNotAccumulateRows() throws Exception
	{
		AccountConnectPlugin p = plugin();
		p.setShopOpenForTest(true);
		p.setStoreToolsForTest(true);
		StoreResetOverlay o = new StoreResetOverlay(p);
		for (int i = 0; i < 25; i++)
		{
			o.render(graphics());
		}
		assertEquals("the panel must not grow across frames", 1, o.builtRowCountForTest());
	}

	@Test
	public void drawsNothingOutsideAShopOrWithoutTheGrant() throws Exception
	{
		AccountConnectPlugin outside = plugin();
		outside.setStoreToolsForTest(true);
		assertNull("no shop, no overlay", new StoreResetOverlay(outside).render(graphics()));

		AccountConnectPlugin ungranted = plugin();
		ungranted.setShopOpenForTest(true);
		assertNull("no grant, no overlay", new StoreResetOverlay(ungranted).render(graphics()));
	}

	@Test
	public void drawsWhileAShopIsOpenAndGranted() throws Exception
	{
		AccountConnectPlugin p = plugin();
		p.setShopOpenForTest(true);
		p.setStoreToolsForTest(true);
		Dimension d = new StoreResetOverlay(p).render(graphics());
		assertNotNull(d);
	}

	@Test
	public void theWaitingStateIsNamedAndNeutral() throws Exception
	{
		// A blank or red waiting state is the failure: blank looks broken, red is a standing
		// "do not hand off" warning on a shop that has never reset.
		AccountConnectPlugin p = plugin();
		p.setShopOpenForTest(true);
		p.setStoreToolsForTest(true);
		StoreResetOverlay o = new StoreResetOverlay(p);
		o.render(graphics());
		assertEquals("sell junk", o.lastTextForTest());
		org.junit.Assert.assertNotEquals("waiting must not look urgent",
			StoreResetOverlay.countdownColor(1), o.lastColorForTest());
	}

	@Test
	public void theCountdownRoundsUpAndNeverShowsZero()
	{
		assertEquals("sell junk", StoreResetOverlay.resetText(0));
		assertEquals("sell junk", StoreResetOverlay.resetText(-5));
		assertEquals("1s", StoreResetOverlay.resetText(1));
		assertEquals("rounds up", "1s", StoreResetOverlay.resetText(999));
		assertEquals("13s", StoreResetOverlay.resetText(12_500));
		assertEquals("60s", StoreResetOverlay.resetText(60_000));
	}

	@Test
	public void theColourBandsAreDistinctAndOrdered()
	{
		java.awt.Color safe = StoreResetOverlay.countdownColor(StoreResetOverlay.SAFE_SECONDS);
		java.awt.Color mid = StoreResetOverlay.countdownColor(StoreResetOverlay.URGENT_SECONDS + 1);
		java.awt.Color urgent = StoreResetOverlay.countdownColor(StoreResetOverlay.URGENT_SECONDS);
		org.junit.Assert.assertNotEquals(safe, mid);
		org.junit.Assert.assertNotEquals(mid, urgent);
		org.junit.Assert.assertNotEquals(safe, urgent);
		assertTrue("urgent reads red", urgent.getRed() > urgent.getGreen());
		assertTrue("safe reads green", safe.getGreen() > safe.getRed());
	}

	@Test
	public void theUrgentBandIsInclusiveOfItsBoundary()
	{
		assertEquals(StoreResetOverlay.countdownColor(StoreResetOverlay.URGENT_SECONDS),
			StoreResetOverlay.countdownColor(1));
		org.junit.Assert.assertNotEquals(
			StoreResetOverlay.countdownColor(StoreResetOverlay.URGENT_SECONDS),
			StoreResetOverlay.countdownColor(StoreResetOverlay.URGENT_SECONDS + 1));
	}
}

package com.osrsbestinslot.export;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import com.google.gson.Gson;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.Dispatcher;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

/**
 * PRODUCTION-EQUIVALENT INGEST CONTRACT — opt-in, network-dependent.
 *
 * <p>Everything else in this suite runs against a local MockWebServer. This class additionally checks
 * the payload the plugin actually builds against the REAL production ingest endpoint, because a locally
 * green test proves the client is self-consistent, not that the server accepts what it emits.
 *
 * <p><b>It writes nothing.</b> The token used is a syntactically valid but unowned 32-hex string, so
 * production replies {@code {"ok":true,"stored":0}} — the request is parsed and accepted, and zero rows
 * are persisted. That is exactly the signal wanted: schema acceptance without touching customer data.
 *
 * <p>Skipped unless {@code -DrunProdContract=true}, so the normal offline build stays hermetic and CI
 * never depends on the network.
 */
public class ProductionIngestContractTest
{
	private static final String PROD = "https://www.osrsbestinslot.com/wp-json/osrsbis/v1";
	/** Valid shape, owned by nobody → parsed and accepted, stored:0. */
	private static final String UNOWNED_TOKEN = "0123456789abcdef0123456789abcdef";

	private AccountConnectPlugin plugin;
	private MockWebServer proxy;

	/**
	 * Opt-in switch. Reads an ENV VAR, not a system property: Gradle forks the test JVM and does not
	 * forward {@code -D} flags to it unless build.gradle explicitly wires them, so a system-property
	 * gate silently evaluated false and these tests reported PASS in 0.376s without executing a single
	 * assertion — a false green, which is worse than no test. Env vars are inherited by the fork.
	 */
	private static boolean enabled()
	{
		return "true".equals(System.getenv("RUN_PROD_CONTRACT"));
	}

	/** Fails loudly if an enabled run somehow skips, so a silent no-op can never look like a pass again. */
	private static void requireEnabled()
	{
		if (!enabled())
		{
			throw new IllegalStateException("prod contract test ran without RUN_PROD_CONTRACT=true");
		}
	}

	@Before
	public void setUp() throws Exception
	{
		plugin = new AccountConnectPlugin();
		inject("gson", new Gson());
		inject("okHttpClient", new OkHttpClient.Builder()
			.connectTimeout(10, TimeUnit.SECONDS)
			.readTimeout(10, TimeUnit.SECONDS)
			.build());
	}

	@After
	public void tearDown() throws Exception
	{
		if (proxy != null)
		{
			proxy.shutdown();
		}
	}

	private void inject(String fieldName, Object value) throws Exception
	{
		Field f = AccountConnectPlugin.class.getDeclaredField(fieldName);
		f.setAccessible(true);
		f.set(plugin, value);
	}

	private void pointAt(String baseUrl)
	{
		AccountConnectConfig config = mock(AccountConnectConfig.class);
		when(config.enableUpload()).thenReturn(true);
		when(config.linkToken()).thenReturn(UNOWNED_TOKEN);
		when(config.apiBaseUrl()).thenReturn(baseUrl);
		try
		{
			inject("config", config);
		}
		catch (Exception e)
		{
			throw new RuntimeException(e);
		}
	}

	private void seed(String type, Map<String, Object> fields)
	{
		Map<String, Object> ev = new LinkedHashMap<>();
		ev.put("type", type);
		ev.put("ts", System.currentTimeMillis());
		ev.putAll(fields);
		synchronized (plugin.pendingEvents)
		{
			plugin.pendingEvents.add(ev);
		}
	}

	/**
	 * The 0.7.4 trade payload — counterparty + itemised received[] — is ACCEPTED by production.
	 *
	 * <p>This is the schema half of the trade validation. It proves the server takes the new fields
	 * (which it does opaquely: `fields` is stored as a JSON blob, so no server change is needed). It does
	 * NOT prove the widget read works in a live client — only a genuine two-sided in-game trade can, and
	 * that is recorded as a separate manual step.
	 */
	@Test
	public void productionAcceptsTheNew074TradePayload() throws Exception
	{
		if (!enabled())
		{
			return;
		}
		requireEnabled();
		pointAt(PROD);
		Map<String, Object> fields = new LinkedHashMap<>();
		List<Map<String, Object>> given = new ArrayList<>();
		Map<String, Object> g = new LinkedHashMap<>();
		g.put("id", 995);
		g.put("qty", 1_000_000);
		given.add(g);
		List<Map<String, Object>> received = new ArrayList<>();
		Map<String, Object> r = new LinkedHashMap<>();
		r.put("id", 4151);
		r.put("qty", 1);
		received.add(r);
		fields.put("given", given);
		fields.put("received", received);		// 0.7.4: itemised, was always []
		fields.put("counterparty", "ZZZ_CONTRACT_TEST");	// 0.7.4: was never present
		seed("trade", fields);

		plugin.flushEvents();
		Thread.sleep(4000);

		synchronized (plugin.pendingEvents)
		{
			assertTrue("a 2xx from production must drain the buffer — if this fails the payload was "
				+ "rejected and requeued", plugin.pendingEvents.isEmpty());
		}
		assertEquals("a successful delivery resets the backoff ladder", 0L, plugin.eventRetryBackoffMs);
	}

	/**
	 * The 0.7.4 store payload with an exact gp_total and NO unit_price_gp (the merged-quantity case) is
	 * accepted by production.
	 */
	@Test
	public void productionAcceptsTheMergedStorePayload() throws Exception
	{
		if (!enabled())
		{
			return;
		}
		requireEnabled();
		pointAt(PROD);
		Map<String, Object> fields = AccountConnectPlugin.buildStoreTxFields(
			"store_buy", 453, 20, 1_000_000L, 998_000L, false, true);
		assertEquals(2_000L, fields.get("gp_total"));
		assertTrue("merged qty must carry no unit price", !fields.containsKey("unit_price_gp"));
		seed("store_buy", fields);

		plugin.flushEvents();
		Thread.sleep(4000);

		synchronized (plugin.pendingEvents)
		{
			assertTrue("production must accept the merged store payload", plugin.pendingEvents.isEmpty());
		}
	}

	/**
	 * REAL-WORLD RETRY: a forced 429 in front of the REAL production endpoint.
	 *
	 * <p>A local proxy returns 429 for the first attempt and transparently forwards the second to
	 * production. So the failure is injected, but the eventual delivery is a genuine production accept —
	 * proving the batch survives a rate-limit against the live server and lands exactly once.
	 */
	@Test
	public void forced429InFrontOfProductionRetriesAndLandsExactlyOnce() throws Exception
	{
		if (!enabled())
		{
			return;
		}
		requireEnabled();
		final AtomicInteger attempts = new AtomicInteger();
		final List<String> bodies = new ArrayList<>();
		proxy = new MockWebServer();
		proxy.setDispatcher(new Dispatcher()
		{
			@Override
			public MockResponse dispatch(RecordedRequest request)
			{
				int n = attempts.incrementAndGet();
				synchronized (bodies)
				{
					bodies.add(request.getBody().readUtf8());
				}
				if (n == 1)
				{
					return new MockResponse().setResponseCode(429).setHeader("Retry-After", "1");
				}
				// Second attempt: forward the real payload to production and mirror its status.
				try
				{
					String body;
					synchronized (bodies)
					{
						body = bodies.get(bodies.size() - 1);
					}
					okhttp3.OkHttpClient c = new okhttp3.OkHttpClient();
					okhttp3.Request fwd = new okhttp3.Request.Builder()
						.url(PROD + "/event-ingest")
						.post(okhttp3.RequestBody.create(
							okhttp3.MediaType.parse("application/json"), body))
						.build();
					try (okhttp3.Response resp = c.newCall(fwd).execute())
					{
						String payload = resp.body() == null ? "" : resp.body().string();
						return new MockResponse().setResponseCode(resp.code()).setBody(payload);
					}
				}
				catch (Exception e)
				{
					return new MockResponse().setResponseCode(500);
				}
			}
		});
		proxy.start();
		pointAt(proxy.url("/api").toString().replaceAll("/+$", ""));

		Map<String, Object> fields = new LinkedHashMap<>();
		fields.put("skill", "Attack");
		fields.put("level", 99);
		seed("level_up", fields);

		plugin.flushEvents();				// attempt 1 → 429
		Thread.sleep(2000);
		synchronized (plugin.pendingEvents)
		{
			assertEquals("the batch must survive the 429", 1, plugin.pendingEvents.size());
		}
		assertTrue("the 429 must arm the backoff", plugin.eventRetryBackoffUntilMs > 0);

		plugin.eventRetryBackoffUntilMs = 0L;	// jump the wait rather than sleeping it out
		plugin.flushEvents();				// attempt 2 → forwarded to production
		Thread.sleep(5000);

		synchronized (plugin.pendingEvents)
		{
			assertTrue("production accepted the retry, so the buffer must be empty",
				plugin.pendingEvents.isEmpty());
		}
		assertEquals("exactly two attempts: the refused one and the accepted one", 2, attempts.get());
		synchronized (bodies)
		{
			assertNotNull(bodies.get(0));
			assertEquals("both attempts must carry the same single event", bodies.get(0), bodies.get(1));
		}
	}
}

package com.osrsbestinslot.export;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
